settings103=async function(){await settingsV113Base();let g=document.querySelector('.settings-grid');if(!g)return;let p=jwPrefs(),cfg=p.workspace113||{};g.insertAdjacentHTML('beforeend',`<section class="setting-card setting-wide"><h2>Workspace Defaults</h2><p class="muted">Set conventions that make new work consistent.</p><div class="form"><label>Project code format<input id="wsCode113" value="${esc(cfg.projectCode||'JW-{YYYY}-{###}')}" placeholder="JW-{YYYY}-{###}"></label><label>Revision style<select id="wsRev113"><option value="numeric">0, 1, 2…</option><option value="alpha">A, B, C…</option></select></label><label>Fiscal year starts<select id="wsFiscal113">${['January','April','July','October'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Currency<select id="wsCurrency113"><option>CAD</option><option>USD</option><option>EUR</option><option>GBP</option></select></label><label>Week starts<select id="wsWeek113"><option>Monday</option><option>Sunday</option></select></label><label>Date format<select id="wsDate113"><option>YYYY-MM-DD</option><option>MM/DD/YYYY</option><option>DD/MM/YYYY</option></select></label></div></section><section class="setting-card"><h2>AI Preferences</h2><div class="form"><label>Response detail<select id="wsAiDetail113"><option>Concise</option><option selected>Standard</option><option>Detailed</option></select></label><label>Change behavior<select id="wsAiAction113"><option>Suggest only</option><option>Prepare for approval</option></select></label><label class="wide">Company AI context<textarea id="wsAiContext113" placeholder="Example: We operate critical infrastructure. Contractor work normally occurs overnight.">${esc(cfg.aiContext||'')}</textarea></label></div></section><section class="setting-card"><h2>Project Health Rules</h2><div class="form"><label>Yellow when schedule is late by<input id="wsYellow113" type="number" min="1" value="${Number(cfg.yellowDays||7)}"></label><label>Red when schedule is late by<input id="wsRed113" type="number" min="1" value="${Number(cfg.redDays||30)}"></label><label>Yellow budget variance %<input id="wsYellowBudget113" type="number" min="1" value="${Number(cfg.yellowBudget||5)}"></label><label>Red budget variance %<input id="wsRedBudget113" type="number" min="1" value="${Number(cfg.redBudget||15)}"></label></div></section><section class="setting-card"><h2>Terminology</h2><div class="form"><label>Projects are called<input id="wsProjects113" value="${esc(cfg.projectsTerm||'Projects')}"></label><label>Project Manager is called<input id="wsPm113" value="${esc(cfg.pmTerm||'Project Manager')}"></label><label>Quick Notes are called<input id="wsNotes113" value="${esc(cfg.notesTerm||'Quick Notes')}"></label></div></section><section class="setting-card"><h2>Feature Switches</h2><p class="muted">Simplify JWorks by hiding modules your workspace does not use.</p><div class="toggle-list">${[['roadmap','Roadmap'],['approvals','Approvals'],['projectbuilder','Project Builder'],['templates','Templates'],['reports','Reports'],['automations','Automations']].map(([k,n])=>`<label><span>${n}</span><input type="checkbox" data-feature113="${k}" ${cfg.features?.[k]===false?'':'checked'}></label>`).join('')}</div></section><section class="setting-card setting-wide"><h2>Migration & Onboarding</h2><p class="muted">Moving from Excel? Use the Import Center to download templates, validate existing data, and migrate projects or task lists without retyping them.</p><div class="actions">${btn('Open Import Center',`page='importcenter';render()`,'primary')}${btn('Company Portal',`page='company';render()`)}</div></section><section class="setting-card setting-wide"><div class="between"><div><h2>Save Workspace Configuration</h2><p class="muted">Stores your V11.3 workspace preferences and applies feature visibility immediately.</p></div>${btn('Save Workspace Settings','saveWorkspace113()','primary')}</div></section>`);let map={wsRev113:cfg.revisionStyle,wsFiscal113:cfg.fiscal,wsCurrency113:cfg.currency,wsWeek113:cfg.weekStart,wsDate113:cfg.dateFormat,wsAiDetail113:cfg.aiDetail,wsAiAction113:cfg.aiAction};for(let [id,v] of Object.entries(map))if(v&&$(id))$(id).value=v}
function saveWorkspace113(){let p=jwPrefs(),features={};document.querySelectorAll('[data-feature113]').forEach(x=>features[x.dataset.feature113]=x.checked);p.workspace113={projectCode:val('wsCode113'),revisionStyle:val('wsRev113'),fiscal:val('wsFiscal113'),currency:val('wsCurrency113'),weekStart:val('wsWeek113'),dateFormat:val('wsDate113'),aiDetail:val('wsAiDetail113'),aiAction:val('wsAiAction113'),aiContext:val('wsAiContext113'),yellowDays:Number(val('wsYellow113')),redDays:Number(val('wsRed113')),yellowBudget:Number(val('wsYellowBudget113')),redBudget:Number(val('wsRedBudget113')),projectsTerm:val('wsProjects113'),pmTerm:val('wsPm113'),notesTerm:val('wsNotes113'),features};let hidden=p.hiddenPages||[];Object.entries(features).forEach(([k,on])=>{hidden=hidden.filter(x=>x!==k);if(!on)hidden.push(k)});p.hiddenPages=[...new Set(hidden)];localStorage.setItem(JW_PREF_KEY,JSON.stringify(p));applyPrefs();toast('Workspace settings saved')}


