function v13Health(p){let f=projectFacts(p.id),score=100-(f.over.length*6)-(f.blockedN.length*5);if(f.days!==null&&f.days<14)score-=4;return Math.max(35,Math.min(100,score))}
function v13Attention(){let now=today(),items=[];S.tasks.filter(t=>t.status!=='done'&&v131TaskVisible(t)&&t.due_date&&t.due_date<now).forEach(t=>items.push({rank:1,type:'OVERDUE',title:t.name,sub:`${P(t.project_id)?.name||'Personal'} · due ${t.due_date}`,pid:t.project_id,tid:t.id}));(S.approvals||[]).filter(a=>a.status==='pending').forEach(a=>items.push({rank:2,type:'APPROVAL',title:a.title,sub:`${P(a.project_id)?.name||'Project'} · waiting for a decision`,pid:a.project_id}));S.tasks.filter(t=>t.status!=='done'&&v131TaskVisible(t)&&blocked(t)).forEach(t=>items.push({rank:3,type:'DEPENDENCY',title:t.name,sub:`${P(t.project_id)?.name||'Personal'} · predecessor incomplete`,pid:t.project_id,tid:t.id}));return items.sort((a,b)=>a.rank-b.rank).slice(0,4)}
function v13PortfolioMap(active){return active.slice(0,5).map(p=>{let f=projectFacts(p.id),health=v13Health(p),state=health<65?'critical':health<82?'watch':'good';return `<button class="v13-road-row" onclick="openDetail('${p.id}')"><span><b>${esc(p.name)}</b><small>${f.pct}% · ${esc(p.end_date||'No target')}</small></span><i><em style="width:${Math.max(6,f.pct)}%"></em></i><strong class="${state}">${health}</strong></button>`}).join('')||'<div class="v13-empty">No active projects yet.</div>'}
function commandCenter(){let now=today(),active=S.projects.filter(p=>p.status==='active'),open=S.tasks.filter(t=>t.status!=='done'&&v131TaskVisible(t)),attention=v13Attention(),dueToday=open.filter(t=>t.due_date===now),dueWeek=open.filter(t=>t.due_date&&t.due_date>=now&&t.due_date<=iso(new Date(Date.now()+7*86400000))),health=active.length?Math.round(active.reduce((n,p)=>n+v13Health(p),0)/active.length):100,changes=(S.activity||[]).slice(-3).reverse(),greet=new Date().getHours()<12?'Good morning':new Date().getHours()<17?'Good afternoon':'Good evening';let lead=attention[0];$('main').innerHTML=`<div class="v13-hero"><div><div class="eyebrow">JWORKS · COMMAND CENTER</div><h1>${greet}.</h1><p>${attention.length?`${attention.length} item${attention.length===1?'':'s'} deserve your attention.`:'Your portfolio has no urgent exceptions right now.'}</p></div><div class="actions">${btn('+ Task','taskModal()')}${btn('+ Project','projectModal()','primary')}</div><div class="v13-pulse"><div><span>PORTFOLIO HEALTH</span><strong>${health}%</strong></div><div class="v13-healthbar"><i style="width:${health}%"></i></div><div class="v13-summary"><span><b>${active.length}</b> active projects</span><span><b>${dueWeek.length}</b> due this week</span><span><b>${(S.approvals||[]).filter(x=>x.status==='pending').length}</b> approvals</span></div>${lead?`<button class="v13-insight" onclick="${lead.pid?`openDetail('${lead.pid}')`:`page='today';render()`}"><span>JWORKS NOTICED</span><b>${esc(lead.title)}</b><small>${esc(lead.sub)}</small><em>Review →</em></button>`:''}</div></div>
<div class="v13-main-grid"><section class="v13-section"><div class="v13-section-head"><div><span>01</span><h2>Needs your attention</h2></div><button onclick="page='intelligence';render()">View all →</button></div>${attention.map((a,i)=>`<button class="v13-attention" onclick="${a.tid?`taskDrawer('${a.tid}')`:a.pid?`openDetail('${a.pid}')`:`page='today';render()`}"><span>${String(i+1).padStart(2,'0')}</span><div><b>${esc(a.title)}</b><small>${esc(a.sub)}</small></div><em>${esc(a.type)}</em><strong>›</strong></button>`).join('')||'<div class="v13-empty">Nothing urgent is demanding attention.</div>'}</section>
<section class="v13-section"><div class="v13-section-head"><div><span>02</span><h2>Portfolio pulse</h2></div><button onclick="page='roadmap';render()">Full roadmap →</button></div><div class="v13-roadmap">${v13PortfolioMap(active)}</div></section></div>
<div class="v13-lower"><section class="v13-section compact"><div class="v13-section-head"><div><span>03</span><h2>My day</h2></div><button onclick="page='today';render()">Open My Work →</button></div><div class="v13-day"><strong>${dueToday.length}</strong><span>due today</span><strong>${dueWeek.length}</strong><span>due this week</span><strong>${open.filter(t=>t.priority==='high').length}</strong><span>high priority</span></div></section><section class="v13-section compact"><div class="v13-section-head"><div><span>04</span><h2>Since you were here</h2></div><button onclick="page='notifications';render()">See changes →</button></div>${changes.map(x=>`<div class="v13-change">${esc(x.description)}<small>${esc(x.created_at||'')}</small></div>`).join('')||'<div class="v13-empty">No recent changes.</div>'}</section></div>`}
function projectDetail(){let p=P(projectId);if(!p){projectId=null;return projects()}let ts=S.tasks.filter(t=>t.project_id===p.id),st=projectStats(p.id),f=projectFacts(p.id),health=v13Health(p),more=['milestones','files','notes','meetings','changes','intelligence','history'],primary=['overview','plan','work','financials','documents'];if(!primary.includes(tab)&&!more.includes(tab))tab='overview';let actions=btn('← Projects','projectId=null;render()')+btn('+ Task',`taskModal(null,'${p.id}')`,'primary')+btn('Ask JWorks',`openProjectAI('${p.id}')`);$('main').innerHTML=title(p.status,p.name,p.description,actions)+`<div class="v13-project-strip"><div><span>HEALTH</span><b>${health}</b></div><div><span>COMPLETE</span><b>${st.pct}%</b></div><div><span>OPEN WORK</span><b>${f.open.length}</b></div><div><span>OVERDUE</span><b>${f.over.length}</b></div><div><span>TARGET</span><b>${esc(p.end_date||'—')}</b></div></div><div class="v13-project-nav">${primary.map(t=>`<button class="${tab===t?'active':''}" onclick="tab='${t}';render()">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}<details><summary>More</summary><div>${more.map(t=>`<button onclick="tab='${t}';render()">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}<button onclick="projectModal('${p.id}')">Project settings</button></div></details></div><div id="projectPane"></div>`;let pane=$('projectPane');if(tab==='overview'){let next=ts.filter(t=>t.status!=='done').sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999')).slice(0,5);pane.innerHTML=`<div class="v13-project-overview"><section class="panel"><div class="between"><h2>What needs attention</h2><button class="btn" onclick="tab='work';render()">View work</button></div>${f.over.slice(0,3).map(taskRow).join('')||'<div class="v13-empty">No overdue work.</div>'}</section><section class="panel"><h2>What's next</h2>${next.map(taskRow).join('')||'<div class="v13-empty">No open work.</div>'}</section></div><div class="panel"><h2>Project snapshot</h2><div class="v13-snapshot"><span><small>Asset</small>${esc(p.asset||'—')}</span><span><small>Contractor</small>${esc(p.contractor||'—')}</span><span><small>Estimated</small>${fmt(p.estimated_cost)}</span><span><small>Actual</small>${fmt(p.actual_cost)}</span></div></div>`}else if(tab==='plan'){pane.innerHTML=`<div class="kanban">${[['todo','To do'],['doing','In progress'],['done','Done']].map(([status,label])=>`<div class="lane" ondragover="event.preventDefault()" ondrop="dropKanban(event,'${status}')"><h3>${label} · ${ts.filter(t=>t.status===status).length}</h3>${ts.filter(t=>t.status===status).map(t=>`<div class="taskcard ${blocked(t)?'blocked':''}" draggable="true" ondragstart="event.dataTransfer.setData('task','${t.id}')" onclick="taskDrawer('${t.id}')"><strong>${esc(t.name)}</strong><div class="small muted">${esc(t.due_date||'Unscheduled')} · ${esc(t.priority)}</div></div>`).join('')||'<div class="small muted">Drop tasks here</div>'}</div>`).join('')}</div>`}else if(tab==='work'){pane.innerHTML=`<div class="panel"><div class="between"><h2>Project work</h2>${btn('+ Task',`taskModal(null,'${p.id}')`,'primary')}</div>${ts.map(taskRow).join('')||'<div class="v13-empty">No tasks yet.</div>'}</div>`}else if(tab==='financials'){pane.innerHTML=`<div class="panel"><h2>Financial snapshot</h2><div class="v13-finance"><div><span>Estimated</span><b>${fmt(p.estimated_cost)}</b></div><div><span>Actual</span><b>${fmt(p.actual_cost)}</b></div><div><span>Variance</span><b>${fmt(Number(p.estimated_cost||0)-Number(p.actual_cost||0))}</b></div></div><p class="muted">Detailed cost records remain available through the existing cost and reporting tools.</p></div>`}else if(tab==='documents'||tab==='files'){pane.innerHTML=`<div class="panel"><h2>Project documents</h2><input type="file" onchange="uploadFile(this.files[0],'${p.id}')"><p class="small muted">Project files, drawings, Office documents, images and ZIP files.</p>${filesFor(p.id,null)}</div>`}else if(tab==='milestones'){pane.innerHTML=`<div class="panel"><div class="between"><h2>Milestones</h2>${btn('+ Milestone','milestoneModal()','primary')}</div>${S.milestones.filter(m=>m.project_id===p.id).map(m=>`<div class="listrow"><label><input type="checkbox" ${m.done?'checked':''} onchange="setMilestone('${m.id}',this.checked)"> ${esc(m.title)} <span class="small muted">${esc(m.due_date||'')}</span></label>${btn('Delete',`removeMilestone('${m.id}')`,'danger')}</div>`).join('')||'<div class="v13-empty">No milestones yet.</div>'}</div>`}else if(tab==='notes'){pane.innerHTML=`<div class="panel"><h2>Notes & closeout</h2><label class="small muted">Project notes</label><textarea id="notes" style="width:100%">${esc(p.notes)}</textarea><label class="small muted">Closeout documentation</label><textarea id="closeout" style="width:100%">${esc(p.closeout)}</textarea><p>${btn('Save notes',`saveProjectNotes('${p.id}')`,'primary')}</p></div>`}else{pane.innerHTML=`<div class="panel history"><h2>${tab[0].toUpperCase()+tab.slice(1)}</h2>${S.activity.filter(a=>a.project_id===p.id).slice(-20).reverse().map(a=>`<div class="listrow"><span>${esc(a.description)}</span><span class="small muted">${esc(a.created_at)}</span></div>`).join('')||'<div class="v13-empty">Nothing to show yet.</div>'}</div>`}}
