function taskModal(id,presetProject){let t=T(id)||{project_id:presetProject||projectId||'',priority:'medium',status:'todo',recurring:''},phases=(S.phases||[]).filter(x=>x.project_id===t.project_id);editingTask=id||null;let ps=S.projects.filter(p=>p.status==='active'||p.id===t.project_id).map(p=>`<option value="${p.id}" ${t.project_id===p.id?'selected':''}>${esc(p.name)}</option>`).join(''),deps=S.tasks.filter(x=>x.id!==id).map(x=>`<option value="${x.id}" ${t.depends_on===x.id?'selected':''}>${esc(x.name)}</option>`).join('');modal(id?'Edit task':'Create task',`<form class="form v13-task-form" onsubmit="saveTaskV5(event,'${id||''}')"><label class="wide">What needs to be done?<input id="t_name" required autofocus value="${esc(t.name||'')}" placeholder="Task name"></label><label>Owner<input id="t_assignee" value="${esc(t.assignee||'')}" placeholder="Assignee"></label><label>Due date<input type="date" id="t_due" value="${esc(t.due_date||today())}"></label><label>Priority<select id="t_priority">${['low','medium','high'].map(x=>`<option ${t.priority===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Project<select id="t_project"><option value="">Personal / no project</option>${ps}</select></label><div class="wide"><button type="button" class="v13-details-toggle" id="v13TaskMore" onclick="v13ToggleTaskDetails()">+ Details</button></div><div class="wide hidden v13-task-details" id="v13TaskDetails"><div class="form"><label>Phase<select id="t_phase"><option value="">No phase</option>${phases.map(x=>`<option value="${x.id}" ${t.phase_id===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><label>Status<select id="t_status">${['todo','doing','done'].map(x=>`<option value="${x}" ${t.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Start date<input type="date" id="t_start" value="${esc(t.start_date||t.due_date||today())}"></label><label>Repeat<select id="t_recurring">${['','daily','weekdays','weekly'].map(x=>`<option value="${x}" ${t.recurring===x?'selected':''}>${x||'None'}</option>`).join('')}</select></label><label>Estimated hours<input type="number" step=".25" min="0" id="t_esth" value="${t.estimated_hours||0}"></label><label>Actual hours<input type="number" step=".25" min="0" id="t_acth" value="${t.actual_hours||0}"></label><label>Tags<input id="t_tags" value="${esc(t.tags||'')}" placeholder="design, vendor, urgent"></label><label>Depends on<select id="t_dep"><option value="">No dependency</option>${deps}</select></label><label class="wide">Notes<textarea id="t_notes">${esc(t.notes||'')}</textarea></label></div></div><div class="actions wide">${id?btn('Delete task',`deleteTask('${id}')`,'danger'):''}<button class="btn primary">${id?'Save task':'Create task'}</button></div></form>${id?`<hr><h3>Checklist</h3><div>${checklistFor(id)}</div><div class="toolbar"><input id="newCheck" placeholder="New checklist item"><button class="btn" onclick="addCheck('${id}')">Add</button></div><h3>Attachments</h3><input type="file" onchange="uploadFile(this.files[0],null,'${id}')">${filesFor(null,id)}`:''}`)}

// ===== JWorks 13.1 Simplification & Reliability =====
function v131ProjectState(p){return ['upcoming','active','on_hold','completed'].includes(p.status)?p.status:(['closed','complete'].includes(p.status)?'completed':['planned','planning'].includes(p.status)?'upcoming':'active')}
function v131ProjectIsLive(p){return v131ProjectState(p)==='active'}
function v131TaskVisible(t){let p=t.project_id?P(t.project_id):null;return !p||v131ProjectIsLive(p)}
function v131StateLabel(s){return ({upcoming:'Upcoming',active:'Active',on_hold:'On Hold',completed:'Completed'})[s]||s}
function projects(){let q=(window.projectQuery||'').toLowerCase();$('main').innerHTML=title('Portfolio','Projects','Active work first. Future, paused and completed projects stay available without creating noise.',btn('+ New Project','projectModal()','primary'))+`<div class="toolbar"><input id="projectSearch" placeholder="Search projects…" value="${esc(window.projectQuery||'')}" oninput="window.projectQuery=this.value;projects()"></div><div id="projectList131"></div>`;let groups=[['active',true],['upcoming',false],['on_hold',false],['completed',false]],root=$('projectList131');root.innerHTML=groups.map(([state,open])=>{let a=S.projects.filter(p=>v131ProjectState(p)===state&&(p.name+' '+(p.description||'')+' '+(p.asset||'')).toLowerCase().includes(q));return `<details class="v131-project-group" ${open?'open':''}><summary><b>${v131StateLabel(state)}</b><span>${a.length}</span></summary><div>${a.map(p=>`<button class="v131-project-row" onclick="openDetail('${p.id}')"><span><b>${esc(p.name)}</b><small>${esc(p.asset||p.description||'No description')}</small></span><em>${projectStats(p.id).pct}%</em><strong>›</strong></button>`).join('')||'<div class="v13-empty">No projects in this group.</div>'}</div></details>`}).join('')}
function projectModal(id){let p=P(id)||{status:'active'};modal(id?'Project settings':'New project',`<form class="form" onsubmit="saveProject131(event,'${id||''}')"><label class="wide">Project name<input id="p_name" required value="${esc(p.name||'')}"></label><label>Status<select id="p_status">${['upcoming','active','on_hold','completed'].map(s=>`<option value="${s}" ${v131ProjectState(p)===s?'selected':''}>${v131StateLabel(s)}</option>`).join('')}</select></label><label>Planned start<input type="date" id="p_start" value="${esc(p.start_date||today())}"></label><label>Target date<input type="date" id="p_end" value="${esc(p.end_date||today())}"></label><label class="wide">Description<textarea id="p_description">${esc(p.description||'')}</textarea></label><details class="wide v131-more"><summary>More project details</summary><div class="form"><label>Asset / equipment<input id="p_asset" value="${esc(p.asset||'')}"></label><label>Contractor<input id="p_contractor" value="${esc(p.contractor||'')}"></label><label>PO number<input id="p_po" value="${esc(p.po_number||'')}"></label><label>Estimated cost (CAD)<input type="number" step=".01" min="0" id="p_est" value="${p.estimated_cost||0}"></label><label>Actual cost (CAD)<input type="number" step=".01" min="0" id="p_actual" value="${p.actual_cost||0}"></label><label>Commissioning<select id="p_commissioning">${['not_started','in_progress','passed','failed'].map(s=>`<option ${p.commissioning===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="wide"><span><input type="checkbox" id="p_shutdown" ${p.shutdown_required?'checked':''}> Shutdown required</span></label></div></details><div class="actions wide">${id?btn('Delete project',`deleteProject('${id}')`,'danger'):''}<button class="btn primary">Save project</button></div></form>`)}
async function saveProject131(e,id){e.preventDefault();await run(async()=>{let data={name:val('p_name'),status:val('p_status'),description:val('p_description'),start_date:val('p_start'),end_date:val('p_end'),asset:val('p_asset'),contractor:val('p_contractor'),po_number:val('p_po'),commissioning:val('p_commissioning'),estimated_cost:val('p_est'),actual_cost:val('p_actual'),shutdown_required:$('p_shutdown').checked};let r=await api(id?'projects/'+id:'projects',id?'PATCH':'POST',data);closeModal();await refresh();openDetail(id||r.id)})}
function v131TaskSections(ts){return [['todo','To Do'],['doing','Doing'],['done','Done']].map(([s,label])=>{let a=ts.filter(t=>(s==='doing'?['doing','in_progress'].includes(t.status):t.status===s)).sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999'));return `<details class="v131-task-group" ${s!=='done'?'open':''}><summary><b>${label}</b><span>${a.length}</span></summary><div>${a.map(taskRow).join('')||'<div class="v13-empty">Nothing here.</div>'}</div></details>`}).join('')}
function todayView(){let q=(window.taskQuery||'').toLowerCase(),mine=S.tasks.filter(t=>v131TaskVisible(t)&&(t.name+' '+(t.notes||'')).toLowerCase().includes(q));$('main').innerHTML=title('Workspace','My Work','Focus on work that matters now.',btn('+ Task','taskModal()','primary'))+`<div class="toolbar"><input placeholder="Search tasks…" value="${esc(window.taskQuery||'')}" oninput="window.taskQuery=this.value;todayView()"><button class="btn ${window.v131Due==='overdue'?'primary':''}" onclick="window.v131Due=window.v131Due==='overdue'?'':'overdue';todayView()">Overdue</button><button class="btn ${window.v131Due==='soon'?'primary':''}" onclick="window.v131Due=window.v131Due==='soon'?'':'soon';todayView()">Due soon</button></div><div>${v131TaskSections(mine.filter(t=>!window.v131Due||(window.v131Due==='overdue'?t.status!=='done'&&t.due_date&&t.due_date<today():t.status!=='done'&&t.due_date&&t.due_date>=today())))}</div>`}
function v131Critical(pid){let ts=S.tasks.filter(t=>t.project_id===pid&&t.status!=='done'),by=Object.fromEntries(ts.map(t=>[t.id,t])),memo={};function dur(t){if(t.duration_days)return Math.max(1,Number(t.duration_days));if(t.start_date&&t.due_date)return Math.max(1,Math.round((new Date(t.due_date+'T12:00:00')-new Date(t.start_date+'T12:00:00'))/86400000)+1);return 1}function score(t,seen=new Set()){if(memo[t.id])return memo[t.id];if(seen.has(t.id))return {n:dur(t),path:[t]};let dep=by[t.depends_on];if(!dep)return memo[t.id]={n:dur(t),path:[t]};let r=score(dep,new Set([...seen,t.id]));return memo[t.id]={n:r.n+dur(t),path:[...r.path,t]}}let best={n:0,path:[]};ts.forEach(t=>{let r=score(t);if(r.n>best.n)best=r});return best}
function v131Gantt(pid){let p=P(pid),tasks=S.tasks.filter(t=>t.project_id===pid&&t.start_date&&t.due_date),ms=S.milestones.filter(m=>m.project_id===pid&&m.due_date);if(!tasks.length&&!ms.length)return '<div class="v13-empty">Add task dates or milestones to build the schedule.</div>';let dates=[...tasks.flatMap(t=>[t.start_date,t.due_date]),...ms.map(m=>m.due_date)].sort(),start=new Date(dates[0]+'T12:00:00'),end=new Date(dates.at(-1)+'T12:00:00'),span=Math.max(1,Math.round((end-start)/86400000)+1),scale=Math.max(3,Math.min(16,900/span)),critical=new Set(v131Critical(pid).path.map(t=>t.id));let rows=tasks.sort((a,b)=>a.start_date.localeCompare(b.start_date)).map(t=>{let l=Math.round((new Date(t.start_date+'T12:00:00')-start)/86400000)*scale,w=Math.max(10,(Math.round((new Date(t.due_date+'T12:00:00')-new Date(t.start_date+'T12:00:00'))/86400000)+1)*scale);return `<div class="v131-grow"><button onclick="taskDrawer('${t.id}')">${esc(t.name)}</button><div><i class="${critical.has(t.id)?'critical':''}" style="left:${l}px;width:${w}px" title="${esc(t.start_date)} → ${esc(t.due_date)}"></i></div></div>`}).join('');return `<div class="v131-gantt-head"><span>${esc(dates[0])}</span><b>${esc(p.name)}</b><span>${esc(dates.at(-1))}</span></div><div class="v131-gantt-scroll"><div style="min-width:${Math.max(700,span*scale+280)}px">${rows}${ms.map(m=>{let l=Math.round((new Date(m.due_date+'T12:00:00')-start)/86400000)*scale;return `<div class="v131-grow milestone"><span>◆ ${esc(m.title)}</span><div><i style="left:${l}px"></i></div></div>`}).join('')}</div></div>`}
function printGantt131(pid){let p=P(pid),html=v131Gantt(pid),w=window.open('','_blank');w.document.write(`<!doctype html><html><head><title>${esc(p.name)} - Gantt</title><style>@page{size:landscape;margin:.35in}body{font:11px Arial;color:#172033}.v131-gantt-head{display:flex;justify-content:space-between;border-bottom:2px solid #222;padding:8px}.v131-gantt-scroll{overflow:visible}.v131-grow{display:grid;grid-template-columns:220px 1fr;min-height:30px;border-bottom:1px solid #ddd}.v131-grow>button,.v131-grow>span{border:0;background:none;text-align:left;padding:7px}.v131-grow>div{position:relative;background:repeating-linear-gradient(90deg,#fff 0,#fff 29px,#eee 30px)}.v131-grow i{position:absolute;top:7px;height:16px;background:#506477}.v131-grow i.critical{background:#111}.milestone i{width:10px;height:10px;transform:rotate(45deg)}</style></head><body><h1>${esc(p.name)} — Gantt Schedule</h1>${html}<script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function v131Plan(pid){let p=P(pid),ph=S.phases.filter(x=>x.project_id===pid).sort((a,b)=>(a.sort_order||0)-(b.sort_order||0)),cp=v131Critical(pid);return `<div class="v131-plan-actions"><button class="btn primary" onclick="phaseModal()">+ Phase</button><button class="btn" onclick="printGantt131('${pid}')">Print Gantt</button></div><div class="panel v131-plan-block"><div class="between"><h2>Gantt schedule</h2><span class="small muted">All dated project tasks · critical chain shown darker</span></div>${v131Gantt(pid)}</div><div class="v13-project-overview"><div class="panel"><div class="between"><h2>Phases</h2><span>${ph.length}</span></div>${ph.map(x=>`<div class="listrow"><div><b>${esc(x.title)}</b><div class="small muted">${esc(x.start_date||'—')} → ${esc(x.end_date||'—')}</div></div><div>${btn('Edit',`phaseModal('${x.id}')`)} ${btn('Delete',`deletePhase('${x.id}')`,'danger')}</div></div>`).join('')||'<div class="v13-empty">No phases yet.</div>'}</div><div class="panel"><h2>Critical Path</h2>${cp.path.length?`<p><b>${cp.n} planned days</b> across ${cp.path.length} linked open task${cp.path.length===1?'':'s'}.</p>${cp.path.map((t,i)=>`<div class="v131-path"><span>${i+1}</span><div><b>${esc(t.name)}</b><small>${esc(t.start_date||'Unscheduled')} → ${esc(t.due_date||'Unscheduled')}</small></div></div>`).join('')}<p class="small muted">Calculated from current task dependencies and durations. Review dependencies before relying on the result.</p>`:'<div class="v13-empty">Add linked tasks to calculate a critical path.</div>'}</div></div>`}
const projectDetail131Base=projectDetail;projectDetail=function(){projectDetail131Base();let p=P(projectId);if(!p)return;let pane=$('projectPane');if(tab==='plan')pane.innerHTML=v131Plan(p.id);if(tab==='work')pane.innerHTML=`<div class="between" style="margin-bottom:12px"><div><h2 style="margin:0">Project work</h2><span class="small muted">To Do → Doing → Done</span></div>${btn('+ Task',`taskModal(null,'${p.id}')`,'primary')}</div>${v131TaskSections(S.tasks.filter(t=>t.project_id===p.id))}`;let top=document.querySelector('#main .top .actions');if(top){top.insertAdjacentHTML('beforeend',`<button class="btn" onclick="projectModal('${p.id}')">Project settings</button>`);if(v131ProjectState(p)==='upcoming')top.insertAdjacentHTML('beforeend',`<button class="btn primary" onclick="setProjectStatus('${p.id}','active')">Start Project</button>`);if(v131ProjectState(p)==='on_hold')top.insertAdjacentHTML('beforeend',`<button class="btn primary" onclick="setProjectStatus('${p.id}','active')">Resume</button>`);if(v131ProjectState(p)==='active')top.insertAdjacentHTML('beforeend',`<button class="btn" onclick="setProjectStatus('${p.id}','on_hold')">Put On Hold</button>`)}}
async function reportsView(){let templates=[];try{templates=(await api('report-templates')).items||[]}catch(e){}let rules=(S.automation_rules||[]).filter(r=>r.action_type==='report');$('main').innerHTML=title('Workspace','Reports','Build reusable reports across projects without cluttering the project workspace.',btn('+ Create Report','reportBuilder131()','primary'))+`<div class="v13-project-overview"><section class="panel"><h2>Report templates</h2><div class="v131-template"><b>Project Status</b><span>Fast, standardized project update.</span><button class="btn" onclick="quickStatus131()">Create</button></div>${templates.map(t=>`<div class="v131-template"><b>${esc(t.title)}</b><span>Custom report template</span><button class="btn" onclick="reportBuilder131('${t.id}')">Use</button></div>`).join('')||''}</section><section class="panel"><h2>Scheduled reports</h2>${rules.map(r=>`<div class="listrow"><div><b>${esc(r.title)}</b><div class="small muted">${esc(r.trigger_type)}</div></div><label class="pill"><input type="checkbox" ${r.enabled?'checked':''} onchange="toggleRule('${r.id}',this.checked)"> Enabled</label></div>`).join('')||'<div class="v13-empty">No scheduled reports yet.</div>'}</section></div>`}
