function reportBuilder131(){modal('Create Report',`<div class="form"><label class="wide">Report name<input id="rtitle" value="Monthly Project Report"></label><label class="wide">Project<select id="rproject">${S.projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label class="wide"><b>Include</b></label>${[['exec','Executive summary'],['schedule','Schedule / phases'],['financial','Financials'],['risks','Risks & issues'],['work','Work status']].map(x=>`<label><span><input id="r_${x[0]}" type="checkbox" checked> ${x[1]}</span></label>`).join('')}<details class="wide v131-more"><summary>Automation</summary><div class="form"><label>Schedule<select id="rfreq"><option value="">Run manually</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select></label><label>Day / timing note<input id="rwhen" placeholder="e.g. Monday morning"></label></div></details></div><div class="actions">${btn('Cancel','closeModal()')}<button class="btn" onclick="saveReportTemplate131()">Save Template</button><button class="btn primary" onclick="runReport131()">Generate Now</button></div>`)}
