async function platformPortal132(){try{let [m,x]=await Promise.all([api('platform/overview'),api('platform/companies')]),cs=(x.companies||[]).filter(c=>c.login_code!=='JWORKS-OWNER');$('main').innerHTML=ownerTitle132('Platform Overview','Operate JWorks companies, access, configuration and platform health.')+`<div class="metrics"><div class="metric"><strong>${m.active_companies}</strong><span>Active companies</span></div><div class="metric"><strong>${m.active_users}</strong><span>Active users</span></div><div class="metric"><strong>${m.trials}</strong><span>Trials</span></div><div class="metric"><strong>${m.projects}</strong><span>Customer projects</span></div></div><div class="v13-project-overview"><section class="panel"><div class="between"><h2>Companies</h2><button class="btn primary" onclick="newPlatformCompanyV11()">+ Company</button></div>${cs.slice(0,8).map(c=>`<div class="listrow"><div><b>${esc(c.name)}</b><div class="small muted">${esc(c.login_code)} · ${esc(c.plan)} · ${c.seats_used}/${c.seat_limit} seats</div></div><button class="btn" onclick="ownerCompany132('${c.id}')">Manage</button></div>`).join('')||'<div class="v13-empty">No customer companies yet.</div>'}</section><section class="panel"><h2>Platform Pulse</h2><div class="listrow"><span>Tasks stored</span><b>${m.tasks}</b></div><div class="listrow"><span>Reports generated</span><b>${m.reports}</b></div><div class="listrow"><span>Open support tickets</span><b>${m.tickets}</b></div><div class="listrow"><span>Testing candidate</span><b>V13.2</b></div><p class="small muted">Business, marketing and cross-product metrics belong in the future Reylex/Jelix Owner HQ. This portal operates JWorks itself.</p></section></div>`}catch(e){$('main').innerHTML=ownerTitle132('Platform Overview')+`<div class="panel error">${esc(e.message)}</div>`}}
