async function ownerCompany132(id){let x=await api('platform/companies'),c=(x.companies||[]).find(z=>z.id===id);if(!c)return;let ux=await api('platform/companies/'+id+'/users'),us=ux.users||[],flags={};try{flags=JSON.parse(c.feature_flags||'{}')}catch(e){};$('main').innerHTML=ownerTitle132(c.name,`${c.login_code} · Platform-managed customer workspace`,btn('← Companies',"page='ownercompanies';render()"))+`<div class="v13-project-overview"><section class="panel"><h2>Company & License</h2><label>Name<input id="ocName" value="${esc(c.name)}"></label><label>Plan<select id="ocPlan"><option>trial</option><option>standard</option><option>professional</option><option>enterprise</option></select></label><label>Seat limit<input id="ocSeats" type="number" min="1" value="${c.seat_limit}"></label><label>Status<select id="ocStatus"><option>active</option><option>trial</option><option>past_due</option><option>suspended</option><option>cancelled</option></select></label><label>Support email<input id="ocSupport" value="${esc(c.support_email||'')}"></label><label>Idle timeout (minutes)<input id="ocIdle" type="number" min="5" value="${Number(c.inactivity_minutes||10)}"></label><button class="btn primary" onclick="saveOwnerCompany132('${id}')">Save Company</button></section><section class="panel"><h2>Feature Overrides</h2><p class="small muted">Configure what this company can use without changing or redeploying JWorks.</p>${OWNER_MODULES.map(f=>`<label class="listrow"><span>${f.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())}</span><input type="checkbox" data-owner-feature="${f}" ${flags[f]===false?'':'checked'}></label>`).join('')}<button class="btn primary" onclick="saveOwnerFeatures132('${id}')">Save Features</button></section></div><div class="panel"><div class="between"><h2>Users & Permissions</h2><button class="btn primary" onclick="platformAddUserV111('${id}')">+ User</button></div>${us.map(u=>`<div class="listrow"><div><b>${esc(u.username)}</b><div class="small muted">${esc(u.role)} · ${esc(u.status)}</div></div><button class="btn" onclick="platformEditUserV111('${id}','${u.id}','${esc(u.username)}','${u.role}','${u.status}')">Manage</button></div>`).join('')}</div>`;$('ocPlan').value=c.plan;$('ocStatus').value=c.status}
