// ===== JWorks V13.3 · Import validation and fast work controls =====
function jw133ProjectStatus(p){return v131ProjectState(p)}
function jw133Select(id,value,items,fn,caption){return `<select class="jw133-select" aria-label="${caption}" title="${caption}" onclick="event.stopPropagation()" onchange="event.stopPropagation();${fn}('${id}',this.value)">${items.map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${l}</option>`).join('')}</select>`}
async function jw133ProjectChange(id,status){let p=P(id);if(!p||status===p.status)return;try{await api('projects/'+id,'PATCH',{status});p.status=status;projects();toast('Project moved to '+v131StateLabel(status))}catch(e){alert('Could not update project: '+e.message);projects()}}
async function jw133TaskChange(id,field,value){let t=T(id);if(!t||t[field]===value)return;try{await api('tasks/'+id,'PATCH',{[field]:value});t[field]=value;if(field==='status'&&value==='done')t.progress=100;todayView();toast('Task updated')}catch(e){alert('Could not update task: '+e.message);todayView()}}
function jw133TaskRow(t){let p=P(t.project_id),dep=t.depends_on?T(t.depends_on):null;return `<div class="jw133-taskrow"><div class="jw133-taskname"><button onclick="taskDrawer('${t.id}')">${esc(t.name)}</button><div class="jw133-meta">${esc(p?.name||'Personal')} · ${esc(t.due_date||'No due date')}${t.assignee?' · '+esc(t.assignee):''}${dep?' · After: '+esc(dep.name):''}</div></div><div class="jw133-controls">${jw133Select(t.id,t.status==='in_progress'?'doing':t.status,[['todo','To Do'],['doing','Doing'],['on_hold','On Hold'],['done','Done']],'jw133TaskStatus','Task status')}${jw133Select(t.id,t.priority||'medium',[['low','Low'],['medium','Medium'],['high','High']],'jw133TaskPriority','Task priority')}<button class="jw133-open" title="Open task details" onclick="taskDrawer('${t.id}')">↗</button></div></div>`}
function jw133TaskStatus(id,v){jw133TaskChange(id,'status',v)}
function jw133TaskPriority(id,v){jw133TaskChange(id,'priority',v)}
function projects(){let q=(window.projectQuery||'').toLowerCase();$('main').innerHTML=title('Portfolio','Projects','Change project status directly from the list.',btn('+ New Project','projectModal()','primary'))+`<div class="toolbar"><input placeholder="Search projects…" value="${esc(window.projectQuery||'')}" oninput="window.projectQuery=this.value;projects()"></div><div id="jw133Projects"></div>`;let groups=[['active',true],['upcoming',false],['on_hold',false],['completed',false]];let root=$('jw133Projects');root.innerHTML=groups.map(([state,open])=>{let a=S.projects.filter(p=>jw133ProjectStatus(p)===state&&(p.name+' '+(p.description||'')).toLowerCase().includes(q));return `<details class="v131-project-group" ${open?'open':''}><summary><b>${v131StateLabel(state)}</b><span>${a.length}</span></summary>${a.map(p=>`<div class="jw133-projectrow"><button class="jw133-projectname" onclick="openDetail('${p.id}')"><b>${esc(p.name)}</b><small>${esc(p.asset||p.description||'No description')}</small></button><span class="jw133-progress">${projectStats(p.id).pct}%</span>${jw133Select(p.id,jw133ProjectStatus(p),[['upcoming','Upcoming'],['active','Active'],['on_hold','On Hold'],['completed','Completed']],'jw133ProjectChange','Project status')}<button class="jw133-open" onclick="openDetail('${p.id}')" title="Open project">↗</button></div>`).join('')||'<div class="v13-empty">No projects in this group.</div>'}</details>`}).join('')}
function v131TaskSections(ts){return [['todo','To Do'],['doing','Doing'],['on_hold','On Hold'],['done','Done']].map(([s,label])=>{let a=ts.filter(t=>(s==='doing'?['doing','in_progress'].includes(t.status):t.status===s)).sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999'));return `<details class="v131-task-group" ${s!=='done'&&s!=='on_hold'?'open':''}><summary><b>${label}</b><span>${a.length}</span></summary><div>${a.map(jw133TaskRow).join('')||'<div class="v13-empty">Nothing here.</div>'}</div></details>`}).join('')}
function todayView(){let q=(window.taskQuery||'').toLowerCase(),all=S.tasks.filter(t=>v131TaskVisible(t)&&(t.name+' '+(t.notes||'')+' '+(P(t.project_id)?.name||'')).toLowerCase().includes(q));let filter=window.jw133Filter||'all';let mine=all.filter(t=>filter==='all'||(filter==='overdue'?t.status!=='done'&&t.status!=='on_hold'&&t.due_date&&t.due_date<today():filter==='soon'?t.status!=='done'&&t.status!=='on_hold'&&t.due_date&&t.due_date>=today():t.status===filter));$('main').innerHTML=title('Workspace','My Work','Manage status and priority without opening each task.',btn('+ Task','taskModal()','primary'))+`<div class="jw133-toolbar"><input placeholder="Search tasks or projects…" value="${esc(window.taskQuery||'')}" oninput="window.taskQuery=this.value;todayView()"><select aria-label="Filter tasks" onchange="window.jw133Filter=this.value;todayView()">${[['all','All active-project tasks'],['overdue','Overdue'],['soon','Due soon'],['todo','To Do'],['doing','Doing'],['on_hold','On Hold'],['done','Done']].map(([v,l])=>`<option value="${v}" ${filter===v?'selected':''}>${l}</option>`).join('')}</select><span class="jw133-count">${mine.length} tasks</span></div><div>${v131TaskSections(mine)}</div>`}
const jw133TaskModalBase=taskModal;
taskModal=function(id,pid){jw133TaskModalBase(id,pid);let status=$('t_status');if(status&&!Array.from(status.options).some(o=>o.value==='on_hold'))status.insertAdjacentHTML('beforeend','<option value="on_hold">On Hold</option>');let t=T(id);if(status&&t)status.value=t.status==='in_progress'?'doing':t.status};
const jw133ImportPreviewBase=previewImport113;
previewImport113=async function(kind){await jw133ImportPreviewBase(kind);let r=window.jwImport113;if(!r||r.kind!=='tasks')return;let p=$('importPreview113');if(!p)return;let x=r.dependency_count||0;let errors=(r.rows||[]).filter(t=>t.errors?.length);p.insertAdjacentHTML('afterbegin',`<div class="jw133-importnote"><b>Dependency check:</b> ${x} predecessor references recognized. ${errors.length} rows require attention. Dependencies are validated before commit; no silent guessing when task names are ambiguous.</div>`)};
const jw133ImportCommitBase=commitImport113;
commitImport113=async function(){let x=window.jwImport113;if(x?.kind==='tasks'&&x.error_count){alert('Resolve every task import validation error before committing dependencies. Nothing has been imported.');return}await jw133ImportCommitBase()};
// Keep task rows consistent inside project Work and other list views.
taskRow=jw133TaskRow;

// ===== JWorks V13.4 · Safe task reconciliation =====
const jw134ImportBase=importCenterV113;
importCenterV113=function(){jw134ImportBase();let p=$('importPreview113');if(!p)return;p.insertAdjacentHTML('beforebegin',`<section class="panel jw134-reconcile"><h2>Repair existing task dependencies</h2><p class="muted">Safest for reimports: change only predecessor links. Existing task details are not overwritten. Duplicate records must be explicitly matched; no tasks are created or deleted.</p><div class="toolbar"><input id="jw134File" type="file" accept=".xlsx"><button class="btn primary" onclick="jw134Preview()">Preview Dependencies Only</button><button class="btn" onclick="jw134Duplicates()">Inspect Duplicate Tasks</button></div><div id="jw134Output"></div></section>`)};
async function jw134Preview(){let f=$('jw134File')?.files?.[0];if(!f)return alert('Select the task Excel file first.');await run(async()=>{let fd=new FormData();fd.append('file',f);let r=await api('task-reconcile/preview','POST',fd);window.jw134Rows=r.rows; jw134RenderPreview()})}
function jw134Options(items,selected){return `<option value="">Select a record…</option>`+(items||[]).map((t,i)=>`<option value="${esc(t.id)}" ${selected===t.id?'selected':''}>${esc(t.id.slice(0,8))} · ${esc(t.status||'')} · ${esc(t.due_date||'No date')} · ${esc(t.created_at||'')}</option>`).join('')}
function jw134RenderPreview(){let rows=window.jw134Rows||[],bad=rows.filter(r=>!r.target_id||(r.depends_on_label&&!r.predecessor_id));$('jw134Output').innerHTML=`<h3>Dependency-only preview</h3><p>${rows.length} rows · ${bad.length} require a record selection · ${rows.filter(x=>x.depends_on_label).length} predecessor references. Nothing is written until confirmed.</p><div style="overflow:auto;max-height:520px"><table class="company-table"><tr><th>Row</th><th>Task</th><th>Existing task record</th><th>Predecessor record</th><th>Validation</th></tr>${rows.map((r,i)=>`<tr><td>${r.row}</td><td>${esc(r.project_code)} · ${esc(r.name)}</td><td>${r.target_options?.length===1?esc(r.target_id.slice(0,8)):`<select aria-label="Target for row ${r.row}" onchange="jw134Pick(${i},'target_id',this.value)">${jw134Options(r.target_options,r.target_id)}</select>`}</td><td>${r.depends_on_label?`${esc(r.depends_on_label)}<div>${r.predecessor_options?.length===1?esc(r.predecessor_id.slice(0,8)):`<select aria-label="Predecessor for row ${r.row}" onchange="jw134Pick(${i},'predecessor_id',this.value)">${jw134Options(r.predecessor_options,r.predecessor_id)}</select>`}</div>`:'No predecessor'}</td><td>${esc((r.errors||[]).join('; ')||'Ready')}</td></tr>`).join('')}</table></div><div class="actions"><button class="btn primary" ${bad.length?'disabled':''} onclick="jw134Commit()">Apply Dependencies Only (${rows.length} tasks)</button></div><p class="small muted">If tasks share a name, select the exact ID using dates/status. Duplicate cleanup is a separate explicit operation. Always back up D1 first.</p>`}
function jw134Pick(i,k,v){window.jw134Rows[i][k]=v;let rows=window.jw134Rows||[],bad=rows.filter(r=>!r.target_id||(r.depends_on_label&&!r.predecessor_id));let b=$('jw134Output')?.querySelector('button[onclick="jw134Commit()"]');if(b)b.disabled=bad.length>0}
async function jw134Commit(){let rows=window.jw134Rows||[];if(!rows.length||rows.some(r=>!r.target_id||(r.depends_on_label&&!r.predecessor_id)))return alert('Select all ambiguous task and predecessor records.');if(!confirm(`Update dependencies for ${rows.length} existing tasks? No tasks will be created or deleted. Back up D1 before proceeding.`))return;await run(async()=>{let result=await api('task-reconcile/commit','POST',{rows});toast(`Updated ${result.updated} existing tasks; ${result.dependencies} linked predecessors`);await refresh();jw134RenderPreview()})}
async function jw134Duplicates(){await run(async()=>{let r=await api('task-reconcile/duplicates');$('jw134Output').innerHTML=`<h3>Duplicate Task Inspector</h3><p>${r.total_groups} duplicate groups · ${r.total_extra} extra records. This is a read-only inventory unless you explicitly select a cleanup action.</p>${r.groups.map(g=>`<details class="panel"><summary><b>${esc(g.project_code)} · ${esc(g.name)}</b> (${g.count})</summary><table class="company-table"><tr><th>Task ID</th><th>Created</th><th>Status / Due</th><th>Linked records</th></tr>${g.items.map(t=>`<tr><td><code>${esc(t.id)}</code></td><td>${esc(t.created_at||'')}</td><td>${esc(t.status||'')} / ${esc(t.due_date||'')}</td><td>${t.references.tasks} successors · ${t.references.checklist} checklist · ${t.references.attachments} files</td></tr>`).join('')}</table><p class="muted">Cleanup is only allowed when the record has no linked records, no stable import ID and every meaningful field matches the retained task.</p><div class="toolbar"><select id="jw134Keep_${g.items[0].id}">${g.items.map(t=>`<option value="${t.id}">Keep ${t.id.slice(0,8)}</option>`).join('')}</select><select id="jw134Drop_${g.items[0].id}">${g.items.map(t=>`<option value="${t.id}">Delete ${t.id.slice(0,8)}</option>`).join('')}</select><button class="btn" onclick="jw134Delete('${g.items[0].id}')">Check & Remove Exact Duplicate</button></div></details>`).join('')||'<p>No duplicates detected.</p>'}`})}
async function jw134Delete(group){let keep=$('jw134Keep_'+group)?.value,drop=$('jw134Drop_'+group)?.value;if(!keep||!drop||keep===drop)return alert('Choose two different records.');if(!confirm('Delete this one exact duplicate record? Only safe, unreferenced and identical records can be removed. This cannot be undone.'))return;await run(async()=>{await api('task-reconcile/delete-empty-duplicate','POST',{keep_id:keep,delete_id:drop});toast('Exact duplicate removed');await refresh();await jw134Duplicates()})}


// ===== JWorks V13.5 · Customizable Analytics Command Center =====
const JW135_CATALOG=[
 ['projects','Projects by status',['donut','bar','kpi']],['tasks','Tasks by status',['donut','bar','kpi']],
 ['priority','Open tasks by priority',['bar','donut','kpi']],['due','Task due dates',['bar','line','kpi']],
 ['completion','Project completion',['bar','kpi']],['risk','Open risks by severity',['donut','bar','kpi']],
 ['workload','Open workload by assignee',['bar','donut','kpi']],['budget','Project budgets',['bar','kpi']],
 ['milestones','Milestone progress',['donut','bar','kpi']],['approvals','Approval status',['donut','bar','kpi']]
];
const JW135_COLORS=['#22b8f0','#9a78f5','#20c997','#f59e0b','#f472b6','#ef6461','#647ce9','#64d8cb'];
function jw135Key(){return 'jw135_dashboard_'+String(JW11?.session?.company_id||'company')+'_'+String(JW11?.session?.username||'user')}
function jw135Defaults(){return {days:90,project:'all',edit:false,widgets:[{id:'projects',type:'donut',wide:false},{id:'tasks',type:'bar',wide:false},{id:'completion',type:'bar',wide:true},{id:'priority',type:'donut',wide:false},{id:'due',type:'line',wide:false},{id:'risk',type:'bar',wide:false}]}}
function jw135Prefs(){let d=jw135Defaults();try{let x=JSON.parse(localStorage.getItem(jw135Key())||'{}');if(!x||!Array.isArray(x.widgets))return d;return {...d,...x,widgets:x.widgets.filter(w=>JW135_CATALOG.some(c=>c[0]===w.id)).map(w=>({id:w.id,type:w.type,wide:!!w.wide}))}}catch(e){return d}}
function jw135Save(x){try{localStorage.setItem(jw135Key(),JSON.stringify(x))}catch(e){alert('Dashboard preferences could not be saved in this browser.')}jw135Dashboard()}
function jw135Edit(){let p=jw135Prefs();p.edit=!p.edit;jw135Save(p)}
function jw135Set(k,v){let p=jw135Prefs();p[k]=v;jw135Save(p)}
function jw135Widget(id,k,v){let p=jw135Prefs(),w=p.widgets.find(x=>x.id===id);if(!w)return;w[k]=v;jw135Save(p)}
function jw135Toggle(id){let p=jw135Prefs(),i=p.widgets.findIndex(x=>x.id===id);if(i>=0)p.widgets.splice(i,1);else{let c=JW135_CATALOG.find(c=>c[0]===id);p.widgets.push({id,type:c[2][0],wide:false})}jw135Save(p)}
function jw135Move(id,step){let p=jw135Prefs(),i=p.widgets.findIndex(x=>x.id===id),j=i+step;if(i<0||j<0||j>=p.widgets.length)return;[p.widgets[i],p.widgets[j]]=[p.widgets[j],p.widgets[i]];jw135Save(p)}
function jw135Reset(){if(confirm('Reset your dashboard layout and graph settings?'))jw135Save(jw135Defaults())}
function jw135Dataset(id,projects,tasks){let n=arr=>arr.length,counts=(arr,key,labels)=>labels.map(([v,l])=>[l,n(arr.filter(x=>String(x[key]||'').toLowerCase()===v))]);let now=new Date(),days=[0,7,14,30,60,90],date=t=>t?.due_date?new Date(t.due_date+'T12:00:00'):null;
 if(id==='projects')return counts(projects,'status',[['upcoming','Upcoming'],['active','Active'],['on_hold','On Hold'],['completed','Completed']]);
 if(id==='tasks')return [['To Do',n(tasks.filter(t=>t.status==='todo'))],['Doing',n(tasks.filter(t=>['doing','in_progress'].includes(t.status)))],['On Hold',n(tasks.filter(t=>t.status==='on_hold'))],['Done',n(tasks.filter(t=>t.status==='done'))]];
 if(id==='priority')return [['Urgent',n(tasks.filter(t=>t.status!=='done'&&t.priority==='urgent'))],['High',n(tasks.filter(t=>t.status!=='done'&&t.priority==='high'))],['Medium',n(tasks.filter(t=>t.status!=='done'&&t.priority==='medium'))],['Low',n(tasks.filter(t=>t.status!=='done'&&t.priority==='low'))]];
 if(id==='due')return [['Overdue',n(tasks.filter(t=>t.status!=='done'&&date(t)&&date(t)<new Date(new Date().toDateString())))],['Next 7d',n(tasks.filter(t=>t.status!=='done'&&date(t)&&date(t)>=now&&date(t)<=new Date(now.getTime()+7*86400000)))],['8–30d',n(tasks.filter(t=>t.status!=='done'&&date(t)&&date(t)>new Date(now.getTime()+7*86400000)&&date(t)<=new Date(now.getTime()+30*86400000)))],['Later',n(tasks.filter(t=>t.status!=='done'&&date(t)&&date(t)>new Date(now.getTime()+30*86400000)))]];
 if(id==='completion')return projects.slice(0,12).map(p=>[p.name,Math.round(tasks.filter(t=>t.project_id===p.id&&t.status==='done').length/Math.max(1,tasks.filter(t=>t.project_id===p.id).length)*100)]);
 if(id==='risk')return [['High',n((S.issues||[]).filter(x=>x.status==='open'&&x.severity==='high'&&projects.some(p=>p.id===x.project_id)))],['Medium',n((S.issues||[]).filter(x=>x.status==='open'&&x.severity==='medium'&&projects.some(p=>p.id===x.project_id)))],['Low',n((S.issues||[]).filter(x=>x.status==='open'&&x.severity==='low'&&projects.some(p=>p.id===x.project_id)))]];
 if(id==='workload'){let m={};tasks.filter(t=>t.status!=='done').forEach(t=>{let k=t.assignee||'Unassigned';m[k]=(m[k]||0)+1});return Object.entries(m).sort((a,b)=>b[1]-a[1]).slice(0,12)}
 if(id==='budget')return projects.slice(0,12).map(p=>[p.name,Number(p.estimated_cost||0)]);
 if(id==='milestones'){let a=(S.milestones||[]).filter(x=>projects.some(p=>p.id===x.project_id));return [['Complete',n(a.filter(x=>x.done))],['Open',n(a.filter(x=>!x.done))]]}
 if(id==='approvals'){let a=(S.approvals||[]).filter(x=>!x.project_id||projects.some(p=>p.id===x.project_id));return [['Pending',n(a.filter(x=>x.status==='pending'))],['Approved',n(a.filter(x=>x.status==='approved'))],['Other',n(a.filter(x=>!['pending','approved'].includes(x.status)))]]}
 return []}
function jw135Graph(data,type,id){let total=data.reduce((a,b)=>a+Math.max(0,Number(b[1])||0),0),max=Math.max(1,...data.map(x=>Number(x[1])||0)),c=JW135_COLORS;
 if(!data.length)return '<div class="jw135-empty">No records for this selection.</div>';
 if(type==='kpi')return `<div class="jw135-total">${total.toLocaleString()}</div><div class="jw135-legend">${data.map((x,i)=>`<span><i style="background:${c[i%c.length]}"></i>${esc(x[0])}: ${Number(x[1]).toLocaleString()}</span>`).join('')}</div>`;
 if(type==='donut'){let acc=0;let segments=data.map((x,i)=>{let v=Math.max(0,Number(x[1])||0),s=acc;acc+=total?v/total*100:0;return `${c[i%c.length]} ${s}% ${acc}%`});return `<div class="jw135-donut-layout"><div class="jw135-donut" style="background:conic-gradient(${total?segments.join(','):'#354455 0% 100%'})"><div>${total.toLocaleString()}<small>Total</small></div></div><div class="jw135-legend">${data.map((x,i)=>`<span title="${esc(x[0])}"><i style="background:${c[i%c.length]}"></i>${esc(x[0])} <b>${Number(x[1]).toLocaleString()}</b></span>`).join('')}</div></div>`}
 if(type==='line'){let width=520,height=180,coords=data.map((x,i)=>[(i+.5)*width/data.length,height-20-(Math.max(0,Number(x[1])||0)/max)*(height-40)]);return `<svg class="jw135-line" viewBox="0 0 ${width} ${height}" role="img" aria-label="Line chart"><path d="M0 ${height-20} H${width}" stroke="currentColor" opacity=".2" fill="none"/><polyline points="${coords.map(x=>x.join(',')).join(' ')}" fill="none" stroke="${c[0]}" stroke-width="4" stroke-linejoin="round"/>${coords.map((pt,i)=>`<circle cx="${pt[0]}" cy="${pt[1]}" r="5" fill="${c[i%c.length]}"><title>${esc(data[i][0])}: ${data[i][1]}</title></circle>`).join('')}</svg><div class="jw135-axis">${data.map(x=>`<span>${esc(x[0])}</span>`).join('')}</div>`}
 return `<div class="jw135-bars">${data.map((x,i)=>`<div class="jw135-bar-row"><span title="${esc(x[0])}">${esc(x[0])}</span><div class="jw135-track"><div style="width:${Math.max(0,Number(x[1])||0)/max*100}%;background:${c[i%c.length]}"></div></div><b>${Number(x[1]).toLocaleString()}${id==='completion'?'%':''}</b></div>`).join('')}</div>`}
function jw135Dashboard(){let p=jw135Prefs(),projects=S.projects.filter(x=>p.project==='all'||x.id===p.project),tasks=S.tasks.filter(t=>projects.some(x=>x.id===t.project_id)),open=tasks.filter(t=>t.status!=='done'),over=open.filter(t=>t.due_date&&t.due_date<today()),complete=tasks.filter(t=>t.status==='done').length;
 let cards=[['Projects',projects.length,'#22b8f0'],['Open tasks',open.length,'#9a78f5'],['Completed',complete,'#20c997'],['Overdue',over.length,'#f59e0b']];
 let options=JW135_CATALOG.map(c=>`<label class="jw135-option"><input type="checkbox" ${p.widgets.some(w=>w.id===c[0])?'checked':''} onchange="jw135Toggle('${c[0]}')"> ${esc(c[1])}</label>`).join('');
 let graphCards=p.widgets.map(w=>{let c=JW135_CATALOG.find(x=>x[0]===w.id),types=c[2];return `<section class="jw135-widget ${w.wide?'wide':''}"><div class="jw135-widget-head"><h3>${esc(c[1])}</h3>${p.edit?`<div class="jw135-controls"><select aria-label="Chart type" onchange="jw135Widget('${w.id}','type',this.value)">${types.map(t=>`<option value="${t}" ${w.type===t?'selected':''}>${t}</option>`).join('')}</select><button title="Move left" onclick="jw135Move('${w.id}',-1)">←</button><button title="Move right" onclick="jw135Move('${w.id}',1)">→</button><button title="Toggle width" onclick="jw135Widget('${w.id}','wide',${!w.wide})">${w.wide?'½':'↔'}</button><button title="Remove widget" onclick="jw135Toggle('${w.id}')">×</button></div>`:''}</div>${jw135Graph(jw135Dataset(w.id,projects,tasks),types.includes(w.type)?w.type:types[0],w.id)}</section>`}).join('');
 $('main').innerHTML=`<div class="jw135-head"><div><div class="eyebrow">JWORKS · ANALYTICS</div><h1>Command Center</h1><p class="muted">Your projects, work and performance at a glance.</p></div><div class="actions"><button class="btn ${p.edit?'primary':''}" onclick="jw135Edit()">${p.edit?'✓ Done editing':'⚙ Customize Dashboard'}</button></div></div><div class="jw135-filters"><label>Project <select onchange="jw135Set('project',this.value)"><option value="all">All projects</option>${S.projects.map(x=>`<option value="${esc(x.id)}" ${p.project===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><span class="small muted">Live workspace totals · Individual dashboard settings</span></div><div class="jw135-metrics">${cards.map(([name,value,color])=>`<div class="jw135-metric" style="--metric:${color}"><span>${name}</span><strong>${value.toLocaleString()}</strong></div>`).join('')}</div>${p.edit?`<section class="jw135-editor"><div><h2>Choose your analytics</h2><p class="small muted">Select widgets, chart types, widths and display order. Changes save automatically in this browser.</p></div><div class="jw135-options">${options}</div><button class="btn" onclick="jw135Reset()">Reset layout</button></section>`:''}<div class="jw135-grid">${graphCards||'<div class="jw135-empty">Choose Customize Dashboard to add your first graph.</div>'}</div><p class="small muted" style="margin-top:16px">Charts use your current JWorks records. Dashboard preferences are stored per user in this browser, not yet synced across devices.</p>`;
}
