/* JWorks 13.6 — Adaptive Workspace: additive enhancement, retains existing application APIs. */
const JW136_FEATURES=[['financials','Financials & budgets'],['whatif','What-if analysis'],['risks','Risks & issues'],['intelligence','Intelligence & AI'],['health','Project health'],['lessons','Lessons learned'],['approvals','Approvals'],['meetings','Meeting actions'],['gantt','Gantt & schedules'],['analytics','Analytics & graphs'],['procurement','Procurement'],['changes','Change management'],['milestones','Milestones'],['documents','Documents']];
function jw136Key(s){return 'jw136_'+s+'_'+String(JW11?.session?.company_id||'company')+'_'+String(JW11?.session?.username||'user')}
function jw136Get(s,d){try{let x=JSON.parse(localStorage.getItem(jw136Key(s)));return x===null?d:x}catch(e){return d}}
function jw136Put(s,x){try{localStorage.setItem(jw136Key(s),JSON.stringify(x))}catch(e){alert('Could not save preferences in this browser.')}}
function jw136FeatureOn(id,pid){let personal=jw136Get('features',{}),project=pid?jw136Get('project_'+pid,{}):{};return personal[id]!==false&&project[id]!==false}
function jw136FeatureToggle(id,checked,pid){let key=pid?'project_'+pid:'features',x=jw136Get(key,{});x[id]=checked;jw136Put(key,x);if(pid)render();else jw136Settings()}
function jw136ProjectSettings(){let p=P(projectId);if(!p)return;let v=jw136Get('project_'+p.id,{});$('main').innerHTML=title('Project preferences',p.name,'Show only the sections this project needs.',btn('← Back to project',`page='projects';render()`))+`<section class="jw136-surface"><h2>Project feature visibility</h2><p class="muted">Hidden sections keep their data. Personal preferences also apply.</p><div class="jw136-toggle-grid">${JW136_FEATURES.map(([id,label])=>`<label class="jw136-switch"><span>${label}</span><input type="checkbox" ${v[id]===false?'':'checked'} onchange="jw136FeatureToggle('${id}',this.checked,'${p.id}')"></label>`).join('')}</div><p><button class="btn" onclick="jw136Put('project_${p.id}',{});jw136ProjectSettings()">Reset project visibility</button></p></section>`}
function jw136DashboardPrefs(){let p=jw135Prefs();p.showMetrics=p.showMetrics!==false;p.defaultView=p.defaultView||'list';p.preset=p.preset||'custom';return p}
function jw136UpdateDashboard(k,v){let p=jw136DashboardPrefs();p[k]=v;jw135Save(p);if(page==='settings')jw136Settings()}
function jw136Preset(name){let p=jw136DashboardPrefs();p.preset=name;if(name==='simple'){p.widgets=[{id:'tasks',type:'list',wide:true}];p.showMetrics=false;p.defaultView='list'}else if(name==='standard'){p.widgets=[{id:'projects',type:'list',wide:false},{id:'tasks',type:'list',wide:false},{id:'due',type:'list',wide:true}];p.showMetrics=true;p.defaultView='list'}else if(name==='advanced'){p=jw135Defaults();p.defaultView='bar';p.showMetrics=true;p.preset='advanced'}jw135Save(p);jw136Settings()}
function jw136DashboardSettings(){let p=jw136DashboardPrefs();return `<section class="jw136-surface"><div class="jw136-section-head"><div><h2>Dashboard layout</h2><p class="muted">Choose exactly what you want to see. Even one widget can fill your workspace.</p></div><button class="btn" onclick="jw135Reset();jw136Settings()">Reset layout</button></div><div class="jw136-form-row"><label>Starting layout<select onchange="jw136Preset(this.value)">${[['custom','Custom'],['simple','Simple'],['standard','Standard'],['advanced','Advanced']].map(([v,l])=>`<option value="${v}" ${p.preset===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Preferred display<select onchange="jw136UpdateDashboard('defaultView',this.value)"><option value="list" ${p.defaultView==='list'?'selected':''}>List — no graphs</option><option value="kpi" ${p.defaultView==='kpi'?'selected':''}>Summary numbers</option><option value="bar" ${p.defaultView==='bar'?'selected':''}>Graphs</option></select></label></div><label class="jw136-switch"><span>Show summary metrics across the top</span><input type="checkbox" ${p.showMetrics?'checked':''} onchange="jw136UpdateDashboard('showMetrics',this.checked)"></label><h3>Visible widgets</h3><div class="jw136-widget-list">${JW135_CATALOG.map(([id,label,types])=>{let w=p.widgets.find(w=>w.id===id);return `<div class="jw136-widget-row"><label><input type="checkbox" ${w?'checked':''} onchange="jw135Toggle('${id}');jw136Settings()"> ${esc(label)}</label>${w?`<div class="jw136-widget-actions"><select aria-label="Display for ${esc(label)}" onchange="jw135Widget('${id}','type',this.value);jw136Settings()">${[['list','List'],['kpi','Summary'],...types.filter(t=>t!=='kpi').map(t=>[t,t[0].toUpperCase()+t.slice(1)])].map(([v,l])=>`<option value="${v}" ${w.type===v?'selected':''}>${l}</option>`).join('')}</select><button class="btn" title="Move earlier" onclick="jw135Move('${id}',-1);jw136Settings()">↑</button><button class="btn" title="Move later" onclick="jw135Move('${id}',1);jw136Settings()">↓</button><button class="btn" title="Toggle full width" onclick="jw135Widget('${id}','wide',${!w.wide});jw136Settings()">${w.wide?'Half':'Full'}</button></div>`:''}</div>`}).join('')}</div></section>`}
function jw136Settings(){let section=window.jw136Section||'dashboard';let nav=[['dashboard','Dashboard'],['features','My features'],['appearance','Appearance & preferences']];$('main').innerHTML=title('Personalize JWorks','Settings','A workspace that adapts to the way you work.')+`<div class="jw136-settings"><aside class="jw136-settings-nav">${nav.map(([id,label])=>`<button class="${section===id?'active':''}" onclick="window.jw136Section='${id}';jw136Settings()">${label}</button>`).join('')}</aside><div class="jw136-settings-content">${section==='dashboard'?jw136DashboardSettings():section==='features'?`<section class="jw136-surface"><h2>My feature visibility</h2><p class="muted">Hide capabilities you do not use. Nothing is deleted, and company permissions remain in force.</p><div class="jw136-toggle-grid">${JW136_FEATURES.map(([id,label])=>`<label class="jw136-switch"><span>${label}</span><input type="checkbox" ${jw136Get('features',{})[id]===false?'':'checked'} onchange="jw136FeatureToggle('${id}',this.checked)"></label>`).join('')}</div><button class="btn" onclick="jw136Put('features',{});jw136Settings()">Reset my features</button></section>`:`<section class="jw136-surface"><h2>Appearance & preferences</h2><p class="muted">Your existing workspace, mobile, AI and regional preferences remain available below.</p><div id="jw136OriginalSettings"></div></section>`}</div></div>`;if(section==='appearance'){Promise.resolve(settingsV1201()).then(()=>{let root=$('main');if(!root)return;let html=root.innerHTML;root.innerHTML=title('Personalize JWorks','Settings','Appearance and existing preferences')+`<div class="jw136-settings"><aside class="jw136-settings-nav">${nav.map(([id,label])=>`<button class="${section===id?'active':''}" onclick="window.jw136Section='${id}';jw136Settings()">${label}</button>`).join('')}</aside><div class="jw136-settings-content jw136-legacy">${html}</div></div>`}).catch(e=>{$('main').insertAdjacentHTML('beforeend',`<p>${esc(e.message)}</p>`)})}}
const jw136OriginalGraph=jw135Graph;
jw135Graph=function(data,type,id){if(type==='list')return `<div class="jw136-data-list">${data.length?data.map(([name,value])=>`<div><span>${esc(name)}</span><strong>${Number(value).toLocaleString()}${id==='completion'?'%':''}</strong></div>`).join(''):'<p class="muted">No records for this selection.</p>'}</div>`;return jw136OriginalGraph(data,type,id)};
function jw136Dashboard(){let p=jw136DashboardPrefs(),projects=S.projects.filter(x=>p.project==='all'||x.id===p.project),tasks=S.tasks.filter(t=>projects.some(x=>x.id===t.project_id)),open=tasks.filter(t=>t.status!=='done'),over=open.filter(t=>t.due_date&&t.due_date<today());let cards=[['Projects',projects.length],['Open tasks',open.length],['Completed',tasks.filter(t=>t.status==='done').length],['Overdue',over.length]];let visible=p.widgets.filter(w=>jw136FeatureOn(w.id==='budget'?'financials':w.id==='risk'?'risks':w.id==='approvals'?'approvals':'analytics'));$('main').innerHTML=`<div class="jw135-head"><div><div class="eyebrow">JWORKS · WORKSPACE</div><h1>Command Center</h1><p class="muted">Your workspace, your way.</p></div></div><div class="jw135-filters"><label>Project <select onchange="jw135Set('project',this.value)"><option value="all">All projects</option>${S.projects.map(x=>`<option value="${esc(x.id)}" ${p.project===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><span class="small muted">Manage dashboard in Settings → Dashboard</span></div>${p.showMetrics?`<div class="jw135-metrics">${cards.map(([name,value])=>`<div class="jw135-metric"><span>${name}</span><strong>${value.toLocaleString()}</strong></div>`).join('')}</div>`:''}<div class="jw135-grid jw136-dashboard-grid ${visible.length===1?'jw136-single':''}">${visible.map(w=>{let c=JW135_CATALOG.find(x=>x[0]===w.id);if(!c)return '';let type=['list','kpi','donut','bar','line'].includes(w.type)?w.type:'list';return `<section class="jw135-widget ${w.wide?'wide':''}"><div class="jw135-widget-head"><h3>${esc(c[1])}</h3><select aria-label="Display ${esc(c[1])}" onchange="jw135Widget('${w.id}','type',this.value)">${[['list','List'],['kpi','Summary'],...c[2].filter(t=>t!=='kpi').map(t=>[t,t[0].toUpperCase()+t.slice(1)])].map(([v,l])=>`<option value="${v}" ${type===v?'selected':''}>${l}</option>`).join('')}</select></div>${jw135Graph(jw135Dataset(w.id,projects,tasks),type,w.id)}</section>`}).join('')||`<section class="jw136-surface"><h2>Make this space yours</h2><p class="muted">No widgets are selected. Open Settings → Dashboard to add one.</p><button class="btn primary" onclick="page='settings';window.jw136Section='dashboard';render()">Open dashboard settings</button></section>`}</div>`}
commandCenter=jw136Dashboard;
