const jw136ProjectsBase=projects;
projects=function(){jw136ProjectsBase();let input=$('main').querySelector('input[placeholder^="Search projects"]');if(input){input.oninput=function(){window.projectQuery=this.value;let tmp=document.createElement('div');let old=$('main');let saved=old.innerHTML;let q=window.projectQuery;let groups=[['active',true],['upcoming',false],['on_hold',false],['completed',false]];let root=$('jw133Projects');if(!root)return;root.innerHTML=groups.map(([state,open])=>{let a=S.projects.filter(p=>jw133ProjectStatus(p)===state&&(p.name+' '+(p.description||'')).toLowerCase().includes(q.toLowerCase()));return `<details class="v131-project-group" ${open?'open':''}><summary><b>${v131StateLabel(state)}</b><span>${a.length}</span></summary>${a.map(p=>`<div class="jw133-projectrow"><button class="jw133-projectname" onclick="openDetail('${p.id}')"><b>${esc(p.name)}</b><small>${esc(p.asset||p.description||'No description')}</small></button><span class="jw133-progress">${projectStats(p.id).pct}%</span>${jw133Select(p.id,jw133ProjectStatus(p),[['upcoming','Upcoming'],['active','Active'],['on_hold','On Hold'],['completed','Completed']],'jw133ProjectChange','Project status')}<button class="jw133-open" onclick="openDetail('${p.id}')" title="Open project">↗</button></div>`).join('')||'<div class="v13-empty">No projects in this group.</div>'}</details>`}).join('')}}};
const jw136TodayBase=todayView;
todayView=function(){jw136TodayBase();let input=$('main').querySelector('input[placeholder^="Search tasks"]');if(input)input.oninput=function(){window.taskQuery=this.value;let pos=this.selectionStart;todayView();let replacement=$('main').querySelector('input[placeholder^="Search tasks"]');if(replacement){replacement.focus();replacement.setSelectionRange(pos,pos)}}};
const jw136SearchBase=searchView;
searchView=function(){jw136SearchBase();let input=$('main').querySelector('input.searchbox');if(input)input.oninput=function(){window.v8q=this.value;let result=this.nextElementSibling;if(result)result.innerHTML=globalResults(this.value)}};
const jw136ProjectBase=projectDetail;
projectDetail=function(){if(tab==='jw136settings')return jw136ProjectSettings();let p=P(projectId);if(!p)return jw136ProjectBase();let tabMap={financials:'financials',intelligence:'intelligence',milestones:'milestones',files:'documents',meetings:'meetings',changes:'changes'};if(tabMap[tab]&&!jw136FeatureOn(tabMap[tab],p.id))tab='overview';jw136ProjectBase();let root=$('main');if(!root)return;let nav=root.querySelector('.v13-project-nav');if(nav){nav.querySelectorAll('button').forEach(b=>{let t=b.textContent.trim().toLowerCase();let key={financials:'financials',intelligence:'intelligence',milestones:'milestones',files:'documents',meetings:'meetings',changes:'changes'}[t];if(key&&!jw136FeatureOn(key,p.id))b.remove()});let more=nav.querySelector('details>div');if(more)more.insertAdjacentHTML('beforeend',`<button onclick="tab='jw136settings';render()">Customize project view</button>`)}let strip=root.querySelector('.v13-project-strip');if(strip){if(!jw136FeatureOn('health',p.id))strip.querySelector('div:first-child')?.remove()}if(tab==='overview'){if(!jw136FeatureOn('financials',p.id)){root.querySelectorAll('.panel,.v13-project-overview section').forEach(el=>{let h=el.querySelector('h2');if(h&&/financial|budget|cost/i.test(h.textContent))el.remove()})}}};
const jw136RenderBase=render;
render=function(){if(page==='settings')return jw136Settings();return jw136RenderBase()};


