function jw137Article(id){let a=JW137_KB.find(x=>x[0]===id);if(!a)return;modal(a[1],`<p class="muted">${esc(a[3])}</p><ol class="jw137-article-steps">${a[4].map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="actions"><button class="btn" onclick="closeModal()">Close</button><button class="btn primary" onclick="closeModal();jw137SupportTab('submit')">Still need help? Submit an issue</button></div>`)}
