function jw137FilterKb(){let q=($('jw137KbSearch')?.value||'').toLowerCase();document.querySelectorAll('[data-kb-id]').forEach(el=>{el.hidden=!el.textContent.toLowerCase().includes(q)})}
async function jw137LoadTickets(){let box=$('jw137TicketList');if(!box)return;try{let data=await api('support-tickets');let tickets=data.tickets||[];box.innerHTML=tickets.length?tickets.map(t=>`<button class="jw137-ticket" onclick="jw137TicketDetail('${esc(t.id)}')"><span><strong>${esc(t.ticket_number)}</strong><small>${esc(t.subject)}</small></span><span class="jw137-ticket-meta"><span class="jw137-status">${esc(t.status)}</span><small>${esc(t.created_at||'')}</small></span></button>`).join(''):'<div class="empty">No tickets yet. Submit an issue to create your first ticket.</div>'}catch(e){box.innerHTML=`<div class="error">Could not load tickets: ${esc(e.message)}</div>`}}
async function jw137TicketDetail(id){try{let data=await api('support-tickets/'+encodeURIComponent(id));let t=data.ticket;modal('Ticket '+esc(t.ticket_number),`<div class="jw137-ticket-detail"><div><b>Status</b><p>${esc(t.status)}</p></div><div><b>Priority</b><p>${esc(t.priority)}</p></div><div><b>Category</b><p>${esc(t.category)}</p></div><div><b>Created</b><p>${esc(t.created_at)}</p></div></div><h3>${esc(t.subject)}</h3><p class="jw137-description">${esc(t.description)}</p><p class="small muted">Last updated: ${esc(t.updated_at||t.created_at)}. Status changes are made by the support team.</p><div class="actions"><button class="btn" onclick="closeModal()">Close</button></div>`)}catch(e){toast('Unable to open ticket: '+e.message)}}
supportV12=function(){let section=window.jw137SupportSection||'knowledge';let tabs=[['knowledge','Knowledge base'],['submit','Submit issue'],['tickets','My tickets']];$('main').innerHTML=title('JWORKS SUPPORT','Support Center','Find answers, report issues and follow their progress.')+`<div class="jw137-support"><div class="jw137-support-tabs">${tabs.map(([id,label])=>`<button class="${section===id?'active':''}" onclick="jw137SupportTab('${id}')">${label}</button>`).join('')}</div>${section==='knowledge'?`<div class="jw137-help-intro"><h2>How can we help?</h2><p class="muted">Browse practical guides for common JWorks workflows.</p><input id="jw137KbSearch" type="search" placeholder="Search ${JW137_KB.length} help articles…" oninput="jw137FilterKb()" aria-label="Search help articles"></div><div class="jw137-kb-grid">${JW137_KB.map(a=>`<button class="jw137-kb-card" data-kb-id="${a[0]}" onclick="jw137Article('${a[0]}')"><small>${esc(a[2])}</small><strong>${esc(a[1])}</strong><span>${esc(a[3])}</span><em>Read guide →</em></button>`).join('')}</div>`:section==='submit'?`<section class="jw137-support-form"><h2>Submit a support request</h2><p class="muted">We'll create a trackable ticket. Include the steps to reproduce an issue and what you expected to happen.</p><div class="jw137-form-grid"><label class="wide">Subject<input id="supSubject" maxlength="160" placeholder="Brief description of the issue"></label><label>Category<select id="supCategory"><option>Technical issue</option><option>General</option><option>Billing</option><option>Feature request</option></select></label><label>Priority<select id="supPriority"><option>Normal</option><option>High</option><option>Urgent</option></select></label><label class="wide">Details<textarea id="supBody" rows="7" placeholder="What happened? What did you expect? How can we reproduce it?"></textarea></label></div><label class="jw137-diagnostics"><input type="checkbox" id="supDiag" checked> Include application version and browser information (no passwords or project contents)</label><div class="actions"><button class="btn primary" id="jw137Submit" onclick="sendSupportV12()">Create support ticket</button></div><div id="supportResult" role="status" class="jw137-result"></div></section>`:`<section class="jw137-support-form"><div class="between"><div><h2>My support tickets</h2><p class="muted">Review submitted requests and their current status.</p></div><button class="btn" onclick="jw137LoadTickets()">Refresh</button></div><div id="jw137TicketList">Loading tickets…</div></section>`}</div>`;if(section==='tickets')jw137LoadTickets()};
sendSupportV12=async function(){let payload={subject:val('supSubject').trim(),category:val('supCategory'),priority:val('supPriority'),description:val('supBody').trim(),diagnostics:$('supDiag')?.checked?`JWorks 13.7 | ${navigator.userAgent} | page=${page}`:''};let result=$('supportResult');if(!payload.subject||!payload.description){result.textContent='Enter a subject and details before submitting.';return}let button=$('jw137Submit');button.disabled=true;try{let r=await api('support-tickets','POST',payload);result.innerHTML=`Ticket <strong>${esc(r.ticket_number)}</strong> created successfully. <button class="btn" onclick="jw137SupportTab('tickets')">Track ticket</button>`;$('supBody').value=''}catch(e){result.textContent='Ticket could not be created: '+e.message}finally{button.disabled=false}};
calendarView=function(){let m=new Date(month.getFullYear(),month.getMonth(),1),last=new Date(m.getFullYear(),m.getMonth()+1,0),offset=(m.getDay()+6)%7;let days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];let cells=Array(offset).fill('<div class="jw137-cal-blank"></div>');for(let d=1;d<=last.getDate();d++){let key=iso(new Date(m.getFullYear(),m.getMonth(),d));let tasks=S.tasks.filter(t=>t.due_date===key),milestones=S.milestones.filter(t=>t.due_date===key);let events=[...tasks.map(t=>({name:t.name,fn:`taskDrawer('${t.id}')`})),...milestones.map(t=>({name:'◆ '+t.title,fn:`openDetail('${t.project_id}')`}))];let visible=events.slice(0,3);cells.push(`<div class="jw137-calday ${key===today()?'today':''}"><button class="jw137-caldate" onclick="jw137CalendarDay('${key}')">${d}<span class="jw137-count">${events.length?events.length+' items':''}</span></button><div class="jw137-calevents">${visible.map(e=>`<button title="${esc(e.name)}" onclick="${e.fn}">${esc(e.name)}</button>`).join('')}${events.length>3?`<button class="jw137-more" onclick="jw137CalendarDay('${key}')">+${events.length-3} more</button>`:''}</div></div>`)}$('main').innerHTML=title('Schedule','Calendar',m.toLocaleDateString(undefined,{month:'long',year:'numeric'}),btn('←','shiftMonth(-1)')+btn('Today','month=new Date();render()')+btn('→','shiftMonth(1)'))+`<div class="jw137-calendar"><div class="jw137-calgrid">${days.map(d=>`<div class="jw137-weekday">${d}</div>`).join('')}${cells.join('')}</div></div><p class="small muted">Select a date to view all scheduled tasks and milestones.</p>`};
function jw137CalendarDay(key){let tasks=S.tasks.filter(t=>t.due_date===key),milestones=S.milestones.filter(t=>t.due_date===key);modal('Schedule · '+key,`<div class="jw137-day-list">${tasks.map(t=>`<button onclick="closeModal();taskDrawer('${t.id}')"><b>${esc(t.name)}</b><span>Task</span></button>`).join('')}${milestones.map(t=>`<button onclick="closeModal();openDetail('${t.project_id}')"><b>${esc(t.title)}</b><span>Milestone</span></button>`).join('')||(!tasks.length?'<div class="empty">Nothing scheduled for this date.</div>':'')}</div>`)}


/* JWorks v13.8 — cohesive navigation and settings, and feature visibility. */
const JW138_NAV=[
 ['dashboard','Command Center','⌂'],['projects','Projects','▣'],['today','My Tasks','✓'],['calendar','Calendar','▦'],
 ['reports','Reports','▤'],['portfolio','Portfolio','◫'],['roadmap','Roadmap','▰'],['assistant','Ask JWorks','✦'],
 ['approvals','Approvals','✓'],['inbox','Quick Notes','◎'],['projectbuilder','Project Builder','◇'],['templates','Templates','◇'],
 ['search','Search','⌕'],['notifications','Notifications','◉'],['saved','Saved Views','☆'],['automations','Automations','⚡'],
 ['support','Help & Support','?'],['whatsnew',"What's New",'✦'],['settings','Settings','⚙'],['company','Company Portal','◆'],
 ['importcenter','Import Center','⇧'],['demoworkspace','Demo Workspace','◈'],['platform','JWorks Owner','⬡'],
 ['implementation','Implementation Center','⇄'],['admin','Administration','◉'],['data','Data & Backup','⇅']
];
const JW138_NAV_FEATURE={reports:'analytics',portfolio:'analytics',roadmap:'gantt',approvals:'approvals',assistant:'intelligence',automations:'intelligence'};
function jw138NavPrefs(){return jw136Get('navigation',{pins:['dashboard','projects','today','calendar'],collapsed:false})}
function jw138NavSave(p){jw136Put('navigation',p);jw138BuildNav()}
function jw138NavPin(id,on){let p=jw138NavPrefs();p.pins=on?[...new Set([...p.pins,id])]:p.pins.filter(x=>x!==id);jw138NavSave(p)}
function jw138NavCollapse(){let p=jw138NavPrefs();p.collapsed=!p.collapsed;jw138NavSave(p)}
function jw138NavButton(id){let entry=JW138_NAV.find(x=>x[0]===id);if(!entry)return '';return `<button data-page="${id}" title="${esc(entry[1])}" class="${page===id?'active':''}"><span class="jw138-nav-icon">${entry[2]}</span><span class="jw138-nav-text">${esc(entry[1])}</span></button>`}
function jw138BuildNav(){
 const nav=$('nav');if(!nav)return;
 const prefs=jw138NavPrefs(),owner=JW11?.session?.role==='platform_owner';
 const visible=id=>!JW138_NAV_FEATURE[id]||jw136FeatureOn(JW138_NAV_FEATURE[id]);
 const pinned=prefs.pins.filter(id=>visible(id)&&!['settings','support','company','admin','platform','implementation'].includes(id));
 const excluded=['settings','support','company','admin','platform','implementation','demoworkspace','data','importcenter','whatsnew'];
 const tools=JW138_NAV.filter(x=>!pinned.includes(x[0])&&!excluded.includes(x[0])&&visible(x[0])).map(x=>x[0]);
 const admin=['company','admin','importcenter','data',...(owner?['demoworkspace']:[])];
 nav.innerHTML=`<div class="jw138-nav-top"><span class="jw138-nav-heading">WORKSPACE</span><button class="jw138-collapse" aria-label="${prefs.collapsed?'Expand':'Collapse'} sidebar" title="${prefs.collapsed?'Expand':'Collapse'} sidebar" onclick="jw138NavCollapse()">${prefs.collapsed?'»':'«'}</button></div><div class="jw138-nav-core">${pinned.map(jw138NavButton).join('')}</div><details class="jw138-nav-group"><summary>Explore tools <span>⌄</span></summary><div>${tools.map(jw138NavButton).join('')}</div></details><div class="jw138-nav-bottom">${jw138NavButton('settings')}${jw138NavButton('support')}${jw138NavButton('whatsnew')}<details class="jw138-nav-group"><summary>Administration <span>⌄</span></summary><div>${admin.map(jw138NavButton).join('')}</div></details>${owner?`<details class="jw138-nav-group jw139-owner"><summary>REYLEX owner tools <span>⌄</span></summary><div>${jw138NavButton('platform')}${jw138NavButton('implementation')}</div></details>`:''}</div>`;
 const aside=nav.closest('aside');aside?.classList.toggle('jw138-collapsed',!!prefs.collapsed);
 if(aside){let brand=aside.querySelector('.brand');if(brand){brand.classList.toggle('jw139-brand-compact',!!prefs.collapsed);let mark=brand.querySelector('.jw139-monogram');if(!mark){mark=document.createElement('span');mark.className='jw139-monogram';mark.textContent='JW';brand.appendChild(mark)}}}
 nav.querySelectorAll('button[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
}

function jw138Section(id){window.jw136Section=id;jw138Settings()}
function jw138Features(){let prefs=jw136Get('features',{});let groups=[['Project management',['financials','whatif','risks','health','gantt','milestones','documents']],['Advanced capabilities',['intelligence','analytics','lessons','approvals','meetings','procurement','changes']]];return `<div class="jw138-intro"><h2>My features</h2><p>Keep your workspace focused. Hidden sections retain their data and can be restored anytime.</p></div>${groups.map(([heading,ids])=>`<section class="jw138-settings-section"><h3>${heading}</h3>${ids.map(id=>{let f=JW136_FEATURES.find(x=>x[0]===id);return `<label class="jw138-setting-line"><span>${esc(f?.[1]||id)}</span><input type="checkbox" ${prefs[id]===false?'':'checked'} onchange="jw138SetFeature('${id}',this.checked)"></label>`}).join('')}</section>`).join('')}<button class="btn" onclick="jw136Put('features',{});jw138Settings()">Restore feature defaults</button>`}
function jw138SetFeature(id,on){let x=jw136Get('features',{});x[id]=on;jw136Put('features',x);jw138BuildNav();jw138Settings();toast(on?'Feature shown':'Feature hidden')}
function jw138Appearance(){return `<div class="jw138-intro"><h2>Appearance & preferences</h2><p>Personalize your experience. Organization-wide controls remain in Company Portal.</p></div><section class="jw138-settings-section"><h3>Workspace</h3><div class="jw138-fields"><label>Default landing page<select id="setLanding12"><option value="dashboard">Command Center</option><option value="today">My Tasks</option><option value="projects">Projects</option><option value="intelligence">Intelligence Center</option><option value="roadmap">Roadmap</option></select></label><label>Information density<select id="setDensity12"><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></label></div><label class="jw138-setting-line">Show What's New after releases<input type="checkbox" id="setTours12"></label></section><section class="jw138-settings-section"><h3>AI preferences</h3><div class="jw138-fields"><label>Response detail<select id="setAi12"><option>Concise</option><option>Standard</option><option>Detailed</option></select></label><label>AI change behavior<select id="setAiAction12"><option>Suggest only</option><option>Prepare for approval</option></select></label></div></section><section class="jw138-settings-section"><h3>Mobile shortcuts</h3><div class="jw138-fields"><label>First shortcut<select id="mob112"><option value="dashboard">Home</option><option value="projects">Projects</option><option value="today">My Work</option><option value="intelligence">Intelligence</option></select></label><label>Second shortcut<select id="mob212"><option value="projects">Projects</option><option value="today">My Work</option><option value="roadmap">Roadmap</option><option value="intelligence">Intelligence</option></select></label></div></section><section class="jw138-settings-section"><h3>Regional</h3><div class="jw138-fields"><label>Currency<select id="currency12"><option>CAD</option><option>USD</option><option>EUR</option><option>GBP</option></select></label><label>Week starts<select id="week12"><option>Monday</option><option>Sunday</option></select></label></div></section><div class="jw138-settings-actions"><button class="btn primary" onclick="saveSettingsV1201()">Save preferences</button><button class="btn" onclick="page='company';render()">Company Portal</button></div>`}
async function jw138LoadAppearance(){try{let r=await api('preferences'),p=r.settings||{};let set=(id,v)=>{if($(id)&&v!=null)$(id).value=v};set('setLanding12',p.landing);set('setDensity12',p.density);set('setAi12',p.aiDetail);set('setAiAction12',p.aiAction);set('mob112',p.mobile1);set('mob212',p.mobile2);set('currency12',p.currency);set('week12',p.weekStart);if($('setTours12'))$('setTours12').checked=p.releaseTours!==false}catch(e){}}
function jw138Navigation(){let p=jw138NavPrefs();return `<div class="jw138-intro"><h2>Navigation</h2><p>Choose the tools you use most. Unpinned tools stay accessible under Explore tools.</p></div><section class="jw138-settings-section"><h3>Pin to sidebar</h3>${JW138_NAV.filter(x=>!['settings','support','company','admin','platform','implementation','demoworkspace','data','importcenter','whatsnew'].includes(x[0])&&(!JW138_NAV_FEATURE[x[0]]||jw136FeatureOn(JW138_NAV_FEATURE[x[0]]))).map(([id,name])=>`<label class="jw138-setting-line"><span>${esc(name)}</span><input type="checkbox" ${p.pins.includes(id)?'checked':''} onchange="jw138NavPin('${id}',this.checked);jw138Settings()"></label>`).join('')}</section><button class="btn" onclick="jw138NavSave({pins:['dashboard','projects','today','calendar'],collapsed:false});jw138Settings()">Reset navigation</button>`}
function jw138Settings(){let section=window.jw136Section||'dashboard',items=[['dashboard','Dashboard'],['features','My features'],['navigation','Navigation'],['appearance','Appearance']];let content=section==='dashboard'?jw136DashboardSettings():section==='features'?jw138Features():section==='navigation'?jw138Navigation():jw138Appearance();$('main').innerHTML=title('PERSONALIZE JWORKS','Settings','A simpler workspace, tailored to you.')+`<div class="jw138-settings"><nav class="jw138-settings-tabs" aria-label="Settings sections">${items.map(([id,label])=>`<button class="${section===id?'active':''}" onclick="jw138Section('${id}')">${label}</button>`).join('')}</nav><div class="jw138-settings-body">${content}</div></div>`;if(section==='appearance')jw138LoadAppearance()}
jw136Settings=jw138Settings;
const jw138RenderBase=render;
render=function(){jw138BuildNav();let result=jw138RenderBase();if(page==='projects'&&projectId)jw138ApplyProjectVisibility();return result};
function jw138ApplyProjectVisibility(){let root=$('main');if(!root)return;let pid=projectId;let rules=[['financials',/financial|budget|cost|forecast|expense/i],['whatif',/what.if|scenario/i],['risks',/risk|issue/i],['intelligence',/intelligence|ai insight|ai suggestion/i],['gantt',/gantt|timeline/i],['approvals',/approval/i],['meetings',/meeting/i],['milestones',/milestone/i],['documents',/document|attachment|file/i],['changes',/change management|change request/i]];
root.querySelectorAll('.v13-project-nav button,.v13-project-nav summary,.v13-project-nav a').forEach(el=>{let label=el.textContent.trim();let r=rules.find(([k,re])=>re.test(label));if(r&&!jw136FeatureOn(r[0],pid))el.style.display='none'});
root.querySelectorAll('section,.panel').forEach(el=>{let heading=el.querySelector(':scope > h2,:scope > h3,:scope > header > h2');if(!heading)return;let label=heading.textContent.trim();let r=rules.find(([k,re])=>re.test(label));if(r&&!jw136FeatureOn(r[0],pid))el.style.display='none'});
}
window.addEventListener('DOMContentLoaded',()=>setTimeout(jw138BuildNav,0));

/* v13.9 — apply preferences to dynamically rendered views. Presentation only. */
const JW139_SECTION_RULES=[
 ['financials',/^(financials?|budgets?|costs?|expenses?|financial overview|financial forecast)$/i],
 ['whatif',/^(what[ -]?if|scenario(s| analysis| planning)?)$/i],
 ['risks',/^(risks?|risk register|risk assessment)$/i],
 ['gantt',/^(gantt|timeline|project timeline)$/i],
 ['intelligence',/^(intelligence|ai insights?|ai suggestions?)$/i],
 ['approvals',/^(approvals?|approval center)$/i],
 ['meetings',/^(meetings?|meeting actions)$/i],
 ['procurement',/^(procurement|purchasing)$/i],
 ['documents',/^(documents?|attachments?|files)$/i],
 ['milestones',/^(milestones?)$/i],
 ['changes',/^(change requests?|change management)$/i],
 ['lessons',/^(lessons learned|lessons)$/i],
 ['health',/^(project health|health score)$/i]
];
function jw139Visibility(){
 const root=$('main');if(!root||['settings','company','whatsnew'].includes(page))return;
 const pid=page==='projects'?projectId:null;
 const containers=root.querySelectorAll('.v13-project-nav button,.v13-project-nav a,.v13-project-nav summary,[role="tab"],.project-tabs button,.tabs button,.drawer-tabs button,.v13-project-overview > section,.v13-project-overview > .panel');
 containers.forEach(el=>{
  const label=el.matches('section,.panel')?(el.querySelector('h2,h3')?.textContent||'').trim():el.textContent.trim();
  const match=JW139_SECTION_RULES.find(([id,re])=>re.test(label));
  if(match&&!jw136FeatureOn(match[0],pid))el.hidden=true;
 });
 root.querySelectorAll('section,.panel').forEach(el=>{
  const heading=el.querySelector(':scope > h2,:scope > h3');if(!heading)return;
  const match=JW139_SECTION_RULES.find(([id,re])=>re.test(heading.textContent.trim()));
  if(match&&!jw136FeatureOn(match[0],pid))el.hidden=true;
 });
}
const jw139RenderBase=render;
render=function(){const result=jw139RenderBase();jw138BuildNav();jw139Visibility();if(result&&typeof result.then==='function')return result.then(v=>{jw139Visibility();return v});return result};
const jw139ToggleBase=jw138SetFeature;
jw138SetFeature=function(id,on){jw139ToggleBase(id,on);jw139Visibility()};
// Preserve owner-only routing; surface a useful error if the backend cannot load.
const jw139ImplementationBase=implementationCenterV121;
implementationCenterV121=async function(){try{return await jw139ImplementationBase()}catch(e){$('main').innerHTML=title('REYLEX owner','Implementation Center','Customer onboarding and migrations')+`<section class="panel"><h2>Could not load implementations</h2><p class="muted">${esc(e.message||String(e))}</p><button class="btn" onclick="implementationCenterV121()">Retry</button></section>`}};

const JW139_RELEASES=[{"version": "13.9", "changes": ["Separated REYLEX owner tools from company administration.", "Added a compact sidebar monogram for collapsed navigation.", "Improved feature visibility handling for project tabs and section headings.", "Refined Company Portal form layout and spacing.", "Rebuilt What’s New as a searchable release history sourced from release notes.", "Added a visible retry/error state for Implementation Center loading failures."]}, {"version": "13.9", "changes": ["Sidebar uses JW monogram when collapsed, preventing clipped logo.", "Owner tools separated from customer Administration; Implementation Center remains owner-only.", "Additional project tab/section visibility checks for personal feature preferences.", "Company Portal form fields receive responsive stacked styling and improved spacing.", "What's New replaced by searchable release history compiled from included release notes.", "Implementation Center shows an error/retry state if its API fails.", "Feature visibility is UI-only, not authorization. Some legacy forms and dialogs still need explicit integration and testing."]}, {"version": "13.8", "changes": ["Simplified navigation: configurable pinned primary destinations, Explore tools, Settings/Support, and Administration.", "Collapsible desktop navigation with saved per-user preferences.", "Settings rebuilt with consistent tabs, readable spacing and properly stacked form controls.", "Removed nested legacy Settings page and repeated headings.", "Added navigation personalization and grouped feature visibility.", "Feature toggles update navigation immediately; project detail sections and tabs use the same visibility preferences where identifiable.", "Existing dashboard controls, data, backend, calendar, knowledge base and support tickets retained."]}, {"version": "13.7", "changes": ["Fixed Settings navigation stretching vertically because inherited sidebar styles were affecting its nested navigation.", "Replaced the calendar with a seven-column responsive month grid with a three-item daily preview and clickable full-day schedule.", "Removed the question mark prefix from Support Center navigation.", "Added 16 searchable, clickable Knowledge Base guides with step-by-step content.", "Added Support Center tabs for Knowledge Base, Submit issue, and My tickets.", "Existing ticket submission persists tickets to the Cloudflare-backed support_tickets table.", "Added company-scoped ticket detail API and a ticket detail modal."]}, {"version": "13.6", "changes": ["Settings → Dashboard: widget selection, order, width, chart/list/summary presentation, dashboard metric strip toggle and layout presets.", "Dashboard no longer has a Customize Dashboard button. A single selected widget expands across the available dashboard width.", "Graphs are optional per widget; List and Summary displays are supported.", "Settings → My features: personal feature visibility preferences.", "Project → More → Customize project view: per-project section visibility preferences.", "Settings layout refresh: more whitespace, less dense panels, responsive navigation and form layouts.", "Search input fixes: project search updates results without replacing the input; task search restores focus and caret; global search updates results in place."]}, {"version": "13.5", "changes": ["REYLEX ID / OIDC intentionally deferred; existing authentication unchanged.", "Colorful Command Center with 10 selectable analytics widgets, donut/bar/line/KPI views where applicable.", "Per-user, per-company browser-local saved layout, widget order, width, and graph types.", "Project filtering; metrics computed from existing JWorks data, no mock data.", "No D1 migrations, no server endpoint changes, no task deletion or import actions.", "Dashboard preferences are stored in localStorage on the current browser; they do not yet synchronize across devices.", "Due-date chart is a bucket comparison, not a historical time series. Budget widget displays configured estimated project budgets, not actual spend."]}, {"version": "13.4", "changes": ["Duplicate Task Inspector: company-scoped duplicate groups with task IDs, dates, status, linked task/checklist/attachment counts.", "Guarded exact-duplicate deletion: explicitly choose keep/delete; refuses records with linked data, mismatched task fields or stable external IDs. Does not automatically delete or merge ambiguous records.", "Dependencies Only XLSX workflow: validates project/task names and lets the user choose exact target/predecessor IDs where duplicates exist. No new tasks; preserves task status, dates, assignments and notes. Validates cycles before atomic D1 batch update.", "Stable external task IDs: migration 0013 adds `external_import_id`. The dependency-only importer can read `Task ID` or `External Task ID` if supplied in an XLSX file. Existing spreadsheets without these columns can still use explicit ID selection. External IDs are assigned only when supplied; existing duplicates cannot be automatically disambiguated without user selection.", "Back up the remote D1 database before deployment and before reconciliation.", "The duplicate inspector does not automatically merge records with different data or linked objects. Those must be reviewed manually.", "The current task schema supports one predecessor per task, not a many-to-many dependency graph."]}, {"version": "13.3.1", "changes": ["Replaced browser favicon and PWA icons with JWorks-branded JW icons.", "Added supplied JWorks wordmark and POWERED BY REYLEX to sign-in and workspace sidebar.", "Updated stale V11.1 browser title and PWA name.", "No database, migration, or authentication changes.", "App icons are derived monograms; original supplied wordmark retained for application UI."]}, {"version": "13.3", "changes": ["My Work redesign: direct status and priority dropdowns, no misleading checkbox, clearer task/project/due metadata, filters and On Hold group.", "Project list: inline status changes for Upcoming / Active / On Hold / Completed; project progress remains visible.", "Excel task import: reads `Depends On`, `Assignee`, `Estimated Hours`; resolves predecessor links in a second pass; supports cross-project predecessor syntax `PROJECT-CODE::Task Name`; validates missing/ambiguous/self/circular dependencies; prevents import when validation errors exist; updates matching existing tasks instead of duplicating them.", "Import preview displays recognized predecessor count; import commit returns created, updated and linked counts.", "No database recreation or schema migration in this release.", "Dependencies currently support **one predecessor per task** (`depends_on`). Multiple predecessors and true multi-edge CPM require a separate schema and UI change.", "Task names must be unique within a project for deterministic import. To reference a task in another project use `PROJECT-CODE::Task Name` in `Depends On`."]}, {"version": "13.2", "changes": ["`JWORKS-OWNER` now opens a dedicated JWorks Administration shell rather than the customer project workspace.", "Platform Overview with company/user/project/task/report/support metrics.", "Company administration for plan, seats, status, support configuration and inactivity policy.", "Cross-company user visibility and company-scoped user/role management.", "Per-company feature overrides stored in company configuration rather than source-code edits.", "Platform configuration for customer defaults and controlled platform feature flags.", "Owner-level audit log foundation and System/testing page."]}, {"version": "13.1", "changes": ["Main navigation reduced to Home, Projects, My Work, Reports and Ask JWorks, with secondary tools under More.", "Projects grouped by Active, Upcoming, On Hold and Completed; non-active work no longer competes in normal My Work/dashboard attention.", "Tasks grouped into To Do, Doing and Done, with completed work collapsed by default.", "Project/task forms use progressive disclosure for secondary fields.", "Cloud CRUD for project phases is now implemented.", "Task phase/assignee/hour/tag fields are persisted in D1 via migration 0011.", "Plan workspace combines phases, an all-task project Gantt, milestones and a dependency-based critical path view."]}, {"version": "13.0.0", "changes": ["Replaces the dashboard with a restrained Command Center built around Portfolio Health, the top four attention items, Portfolio Pulse, My Day, and Since You Were Here.", "Removes the prominent AI dashboard block and treats intelligence as an embedded JWorks capability.", "Renames user-facing AI language toward outcomes: Ask JWorks, SOW Studio, Create Actions, Project Builder.", "Simplifies project navigation to Overview, Plan, Work, Financials, Documents + More while retaining advanced tools.", "Adds a project Overview focused on attention, next work, and a concise snapshot.", "Simplifies task creation to task, owner, due date, priority, and project; advanced fields remain behind + Details.", "Preserves existing APIs, D1 schema, demo workspace, migration history, and Cloudflare deployment configuration."]}, {"version": "12.2.1", "changes": ["Fixes a blank/non-responsive Demo Workspace when the demo tracking migration is unavailable.", "Demo Workspace now safely ensures its tracking table/index exist before status/load/reset/clear operations.", "Adds visible loading, success and error states to Demo Workspace.", "Load/Reset/Clear actions now surface API failures instead of failing silently.", "Preserves V12.2 Project Lab and Northstar fictional demo dataset."]}, {"version": "12.2.0", "changes": ["Expands the public Free Tools area into JWorks Project Lab.", "Categories: Build, Calculate, Analyze, Assess and AI.", "Adds Project Rescue, schedule/SOW/RAID/migration analyzers and practical calculators.", "Tools remain usable without creating an account and route naturally into the JWorks trial.", "Adds a fictional Northstar Industries portfolio with eight connected projects.", "Includes tasks, dependencies, milestones, risks/issues, approval, procurement, meeting and decision examples.", "Adds Load, Reset and Clear Demo Data controls."]}, {"version": "12.1", "changes": ["Public Free Tools hub with 12 lead-generating project tools.", "Owner-only Implementation Center with reusable eight-stage customer onboarding.", "Migration Studio presets for monday.com, Asana, ClickUp, Smartsheet, Microsoft Project, Jira, Trello and Excel/CSV.", "Migration workflow emphasizes mapping, validation, dry-run and audit before commit.", "Implementation Packs foundation for repeatable industry configurations.", "New migration: 0009_v12_1_growth_implementation.sql.", "Preserves V12.0.2 deployment/mobile fixes and existing D1/AI architecture."]}, {"version": "12.0.2", "changes": ["Fixed duplicate Flask `preferences_get` endpoint that blocked V12.0.1 deployment.", "Preserved legacy and V12 preference payloads through a single GET `/api/preferences` route.", "Added a real mobile public-site hamburger menu with Product, Solutions, Intelligence, Pricing, Knowledge Base, About, Support, Contact, Sign In and Start Free Trial.", "Fixed authenticated bottom navigation appearing while signed out on mobile.", "Improved public homepage phone layout, typography, cards, Project Pulse demo, footer and public sub-pages.", "Keeps existing D1 migrations; no new migration is required for V12.0.2."]}, {"version": "12.0.1", "changes": ["Repairs Settings with D1-backed per-user preferences.", "Repairs Company Portal and persists branding, feature flags, support email, document branding and inactivity timeout.", "Adds automatic first-login What's New modal for 12.0.1 with Explore/Skip actions.", "Adds 10-minute default inactivity sign-out with a 60-second warning.", "Adds optional support email delivery through the existing `jworks-ai` service binding and Resend. Configure `RESEND_API_KEY` and optionally `SUPPORT_FROM_EMAIL` on `jworks-ai`, then set the destination in Company Portal.", "Replaces public demo examples with fictional, industry-neutral projects.", "Expands the public Intelligence story around practical AI and automation workflows."]}, {"version": "12.0", "changes": ["Bespoke public JWorks marketing site and login/trial funnel", "Logo-only top branding; version moved to sidebar footer", "Mobile More menu with explicit Sign Out", "Collapsible Projects and Plan & Review with remembered state", "Intelligence Center / Project Pulse and portfolio health scoring", "Portfolio Heat Map", "Company Branding & Appearance controls and feature/module switches"]}, {"version": "11.3", "changes": ["Renames Inbox to **Quick Notes** with clearer capture → convert/dismiss workflow.", "Moves **Company Portal** and **JWorks Owner** into the System navigation group.", "Adds **Import Center** with separate Project and Task Excel templates, server-side XLSX preview/validation, project-code matching, and confirmation before import.", "Upgrades Roadmap into a portfolio intelligence view with health, progress, milestones, budget and attention indicators.", "Mobile navigation now respects phone safe areas, uses five aligned destinations, and gives Quick Notes a first-class mobile capture destination.", "Preserves V11.2.8 SOW document controls and the working two-worker AI architecture.", "Includes starter Excel templates directly in the deployed app."]}, {"version": "11.2.8", "changes": ["Editable SOW-specific Project Code; does not modify the underlying project code.", "Editable Revision label (supports 0/1/2 or A/B/C) and Revision Date.", "Revision History table with revision, date, description, and prepared-by fields.", "Removed the internal “Bid / Work Document” warning from contractor-facing print/PDF output.", "[TO CONFIRM] remains available while drafting, but JWorks blocks Approved for Bid / Issued / Awarded documents while unresolved markers remain.", "AI drafting prompt explicitly treats [TO CONFIRM] as an internal drafting marker that must be resolved before issue.", "New D1 migration 0006 adds SOW document-control fields. Existing SOWs remain intact and fall back to their project code / revision 0."]}, {"version": "11.2.7", "changes": ["Based directly on the complete V11.2.6 release.", "Adds a server-side OpenRouter authentication probe inside `jworks-ai`.", "Tests four request-construction methods against `GET https://openrouter.ai/api/v1/key`:", "Each probe records only method, HTTP status, redirect flag, response URL, and provider error. The API key is never returned or logged.", "Uses `redirect: manual` so redirects cannot hide where authentication changes.", "Updates optional OpenRouter app attribution header to current `X-OpenRouter-Title` spelling.", "Chat continues to use native JavaScript `fetch()` with the API key held only by the `jworks-ai` Worker."]}, {"version": "11.2.6", "changes": ["Built directly from the verified V11.2.5 package.", "Replaced the AI Worker outbound OpenRouter request with the literal native JavaScript `fetch()` shape documented by OpenRouter.", "Removed the `Headers` object from the outbound OpenRouter call.", "Normalizes accidental surrounding quotes or a pasted `Bearer ` prefix in the Cloudflare secret.", "Adds safe diagnostics for OpenRouter key format, key length, and outbound header style without exposing the key.", "No D1 migration.", "No tenant, UI, SOW, project, or database changes."]}, {"version": "11.2.5", "changes": ["`jworks-ai` now owns `OPENROUTER_API_KEY` and reads it directly from its own Cloudflare environment.", "Main Python `jworks` Worker no longer reads or forwards the OpenRouter credential.", "Added `/diagnostics` inside the JavaScript AI Worker. It reports only booleans: Worker reached, secret detected, secret non-empty, and Authorization header present.", "OpenRouter key test and chat use the exact same JavaScript-created Authorization headers.", "AI SOW generation now uses the same secure service-binding path without a Python-side key check.", "Updated Test AI Connection UI to show the actual AI Worker state rather than the main Python Worker secret state.", "No D1 migration. Existing company/project data is unchanged."]}, {"version": "11.2.3", "changes": ["Keeps the V11.2.2 two-Worker Cloudflare architecture.", "Reads the JavaScript service-binding response with `Response.json()` through the Python Workers FFI instead of converting `Response.text()` through `str()`.", "Normalizes successful OpenRouter chat responses in `jworks-ai` with explicit `content`, `model`, authentication, and HTTP status fields.", "Treats HTTP 200 from `/api/v1/key` as an authenticated success when OpenRouter reports `ok`.", "Adds a specific error when OpenRouter returns HTTP 200 without a readable assistant message.", "Diagnostic version bumped to 11.2.3."]}, {"version": "11.2.2", "changes": ["`jworks` remains the Git-connected Python Worker at the repository root.", "`jworks-ai` is now isolated under `ai-worker/` with its own Wrangler configuration.", "The root deploy command deploys only `jworks`; it no longer attempts to create/deploy a differently named Worker from the `jworks` CI build.", "`jworks` retains the `AI` service binding targeting `jworks-ai`.", "Platform Owner navigation is hidden from customer-company sessions, with server-side authorization retained.", "Login microphone is anchored to the far right of login fields.", "Long company names in the SOW/report header are protected from clipping."]}, {"version": "11.2.1", "changes": ["Corrects the V11.2 Cloudflare Workers Builds failure where the CI system forced the auxiliary `jworks-ai` deployment to use the connected Worker name `jworks`.", "The AI deployment step now temporarily removes Cloudflare Workers Builds' `WRANGLER_CI_OVERRIDE_NAME` only for the `jworks-ai` deploy.", "The main JWorks deployment remains connected to and deployed as `jworks`.", "Keeps the `AI` service binding pointed at `jworks-ai`.", "JavaScript OpenRouter proxy architecture.", "Platform Owner navigation hidden from customer-company users, with backend authorization enforcement.", "Login microphone anchored to the far-right of the input."]}, {"version": "11.2", "changes": ["Added a dedicated JavaScript Cloudflare Worker (`jworks-ai`) for OpenRouter requests.", "The main Python JWorks Worker calls the AI Worker through a private Cloudflare service binding; the browser never receives the OpenRouter key.", "AI diagnostics now identify the JavaScript AI service separately from OpenRouter key/chat authentication.", "JWorks Owner navigation is hidden for every non-platform-owner session, with an additional client render guard; platform APIs remain protected server-side.", "Sign-in voice controls are initialized on the static login form and pinned to the far-right edge of supported fields.", "Scope of Work cover branding now reserves a protected right column for long company names so decorative cover artwork cannot clip the company name.", "Version updated to 11.2."]}, {"version": "11.1", "changes": ["New Company wizard now creates the company and its initial Company Administrator together.", "Platform Owner can add users to any managed company.", "Company and Platform administrators can change roles, enable/disable accounts, and reset passwords.", "Active-seat limits are enforced when adding or re-enabling users.", "Voice microphone controls are explicitly anchored to the far-right side of supported sign-in inputs.", "Test AI Connection now independently calls OpenRouter `/api/v1/key` before the chat-completions test.", "Diagnostics separately report key endpoint reachability/authentication and chat endpoint authentication."]}, {"version": "11.0", "changes": ["JWorks Platform Owner portal for customer-company administration.", "Company records with generated Company IDs, status, plan and licensed seat counts.", "Company Portal for organization profile, user seats, roles and branding.", "Roles: Platform Owner, Company Administrator, Manager / Project Manager, User and Viewer foundation.", "Login now requires Company ID + username + password.", "14-day self-service trial signup with five seats and generated Company ID.", "Forgot-password token foundation. Email delivery is intentionally not faked and remains unconfigured until a transactional email provider is connected."]}, {"version": "10.3.5", "changes": ["Replaces the 10.3.4 JavaScript `Request`/`Headers` construction path with Cloudflare Python Workers SDK `fetch()` directly.", "Sends the OpenRouter request with `fetch(url, method=\"POST\", headers={...}, body=...)`, matching Cloudflare's documented Python syntax.", "Keeps `OPENROUTER_API_KEY` server-side and never returns or logs its value.", "All JWorks AI features continue to use the same shared `openrouter_chat()` provider path.", "AI diagnostics now identify the transport as `workers.fetch(url, method, headers, body)` and confirm that headers were passed directly.", "No D1 migration.", "No R2 binding."]}, {"version": "10.3.4", "changes": ["Rebuilds the OpenRouter call around an explicit Cloudflare Workers `Request` object.", "Attaches `authorization` directly to the exact Request object sent to `workers.fetch`.", "AI diagnostics now verify that Authorization exists on that outbound Request object before transmission.", "Uses manual redirect handling so credentials cannot be silently forwarded to another host.", "Preserves all 10.3.3 personalization, Report Studio, mobile/PWA, microphone, and light-theme fixes.", "No D1 migration required."]}, {"version": "10.3.3", "changes": ["Reads `OPENROUTER_API_KEY` through Cloudflare Python Workers' documented `workers.env` binding.", "Keeps the key server-side and never returns the key, prefix, length, or Authorization value.", "**Test AI Connection** now reports boolean checkpoints for secret detection, non-empty value, text conversion, Authorization construction, transport, provider reachability, and authentication result.", "Keeps all OpenRouter calls on the shared request path.", "Global contrast pass for buttons, primary/danger actions, navigation, report style selectors, pills, mobile navigation, Ask AI, voice controls, cards, calendars and other interactive controls.", "Light theme buttons no longer retain dark-theme backgrounds/text combinations.", "No D1 migration is required."]}, {"version": "10.3.2", "changes": ["Replaced OpenRouter outbound transport with Cloudflare Python Workers native `workers.fetch`.", "Added safe AI configuration diagnostics without exposing credentials.", "Added per-user cloud-saved personalization: theme, density, accent, landing page, Focus Deck, mobile shortcuts and voice append/replace preference.", "Expanded Report Studio with Quick/Internal, Executive Summary, Professional and Formal Project Report layouts.", "Custom report templates now save visual style, detail level, sections, cover and footer choices.", "Added D1 migration 0004 for per-user preferences."]}, {"version": "10.3.1", "changes": ["Rebuilt OpenRouter authentication request using native JavaScript `Headers` and `RequestInit` objects so the Cloudflare Python/Pyodide FFI does not drop the Authorization header.", "All existing AI features continue to use the shared `openrouter_chat()` path.", "Replaced visible **Dictate** buttons with compact microphone icons embedded inside supported text inputs and text areas.", "Listening state is shown on the microphone icon without adding extra field clutter.", "Preserves JWorks 10.3 mobile/PWA, Settings, users, custom reports, SOW, D1 and Cloudflare deployment architecture."]}, {"version": "10.3.0", "changes": ["Fixed OpenRouter Authorization header handling for Cloudflare/Pyodide.", "Mobile-first responsive layout with bottom navigation.", "Installable PWA manifest, icons and updated offline shell cache.", "Quick Update meeting capture.", "Voice-to-text dictation controls on supported text inputs and textareas.", "Expanded Settings with navigation visibility preferences.", "User creation/deletion for the original administrator."]}, {"version": "10.2.12", "changes": ["Fixed Administration remaining on “Loading system status…” / “Checking…”.", "Added cloud-aware D1 system status.", "Added OpenRouter configuration status without exposing the API key.", "Added Test AI Connection from Administration and AI Settings.", "Replaced obsolete local API-key editor with Cloudflare-secret-aware AI Settings.", "SOW AI now uses `openrouter/free` and returns useful sanitized provider errors.", "Added OpenRouter app headers and safer response parsing."]}, {"version": "10.2.11", "changes": ["Rebuilt the Scope of Work section editor into a wide, responsive document-editing layout.", "Heading and content fields no longer collide; content editors are full-width and auto-grow as text is entered.", "Added clearer section numbering, live heading labels, compact move/remove controls, and a sticky save/preview action bar.", "Rebuilt the Scope of Work print/PDF output as a contractor-ready document with a JWorks cover, project metadata, revision/status blocks, numbered sections, highlighted `[TO CONFIRM]` markers, document-control approval area, and print-friendly Letter formatting.", "Print now opens as a preview first instead of immediately forcing the browser print dialog.", "Fixed the AI Scope loading-state DOM target while working in the SOW module.", "Updated frontend/service-worker cache identifiers to 10.2.11."]}, {"version": "10.2.10", "changes": ["Replaces `hashlib.pbkdf2_hmac` with a Cloudflare Python Worker/Pyodide-compatible salted, iterated SHA-256 password KDF.", "Updates login verification to use the same versioned password-hash format.", "Removes the 12-character password minimum from both frontend first-run setup and backend validation.", "Passwords are still never stored in plaintext; a random per-password salt and derived hash are stored in D1.", "Keeps the 10.2.8 deterministic deployment pipeline and 10.2.7 root asset layout unchanged.", "No D1 migration is required."]}, {"version": "10.2.9", "changes": ["Preserves the working 10.2.8 deployment/static-asset architecture.", "Reworks `/api/setup` into explicit stages: user-state check, password hashing, D1 user insert, and session creation.", "Returns a useful JSON `stage` and `detail` when Cloudflare/Python/D1 fails instead of an opaque HTTP 500.", "Rolls back a newly inserted administrator if session creation fails, preventing a half-created account from locking first-run setup.", "No D1 migration required."]}, {"version": "10.2.8", "changes": ["Preserves the 10.2.7 root asset layout (`/app.js`, `/manifest.json`, `/sw.js`).", "Adds the known-good `wrangler.jsonc` with the real `jworks-db` D1 database ID.", "Contains no R2 / `FILES` binding.", "Deployment now runs `pywrangler sync` only to vendor Python dependencies.", "Removes any generated `.wrangler` deployment redirect before deployment.", "Runs `npx wrangler deploy --config wrangler.jsonc` directly so the checked-in config is the deployment source of truth.", "No D1 migration is required."]}, {"version": "10.2.7", "changes": ["Moves browser assets out of `/static/` and serves them at the public root:", "Updates `index.html` and service-worker references to the new root paths.", "Removes the old `public/static` directory to eliminate duplicate/stale routes.", "Preserves the 10.2.6 API/D1 backend and first-administrator bootstrap.", "No D1 migration is required.", "`wrangler.jsonc` is intentionally not included; keep the repository's working D1 configuration and `run_worker_first: [\"/api/*\"]` setting."]}, {"version": "10.2.5", "changes": ["Fixes Cloudflare ASSETS proxy routing for `/static/app.js`, `/static/manifest.json`, and other static files.", "Preserves the first-administrator bootstrap introduced in 10.2.4.", "Preserves D1 cloud authentication, projects/tasks, Scope of Work Builder, AI/manual/hybrid authoring, and print/save-PDF workflow.", "No D1 migration is required.", "`wrangler.jsonc` is intentionally not included."]}, {"version": "10.2.4", "changes": ["Fixes first-run administrator UI bootstrap at the HTML layer.", "The setup-needed endpoint is queried with no-store before the main app bundle loads.", "Preserves D1 auth, projects/tasks, Scope of Work Builder, AI/manual/hybrid SOW flow, and Print/Save PDF.", "No database migration required.", "wrangler.jsonc intentionally excluded from this patch package."]}, {"version": "10.2.3", "changes": ["Fixes first-administrator screen bootstrap.", "Cache-busts the application JavaScript so Cloudflare/browser service-worker caches cannot leave the old sign-in logic active.", "Makes startup DOM-ready safe.", "Cache-busts session/setup-needed startup requests.", "Preserves D1 cloud backend and Scope of Work Builder / Print to PDF workflow.", "No D1 migration required.", "wrangler.jsonc intentionally excluded so the deployed D1 database ID is not overwritten."]}, {"version": "10.2.2", "changes": ["Fixes first-run administrator detection against Cloudflare D1.", "Adds robust D1 row value access for session/login handling.", "Bumps frontend/service-worker cache to 10.2.2.", "Preserves the 10.2.1 Scope of Work Builder and PDF print workflow.", "wrangler.jsonc is intentionally omitted from this patch so the deployed repository keeps its existing D1 database ID/configuration."]}, {"version": "10.2.1", "changes": ["First-admin setup stored in D1.", "PBKDF2-SHA256 password hashing with per-password salt.", "D1-backed 7-day secure HttpOnly sessions.", "CSRF token validation for authenticated changes.", "Core project/task and common project-record APIs moved from local SQLite patterns to D1."]}];
function jw139WhatsNew(){
 const releases=JW139_RELEASES;
 $('main').innerHTML=title('PRODUCT UPDATES','What’s New in JWorks','A release-by-release record of improvements, fixes, and known limitations.')+`<div class="jw139-release-hero"><div class="eyebrow">CURRENT TESTING RELEASE</div><h2>JWorks v13.9</h2><p>Navigation, workspace reliability and UI refinement</p><div class="jw139-release-stats"><span>${releases.length} documented releases</span><span>Release notes included in this package</span></div></div><div class="jw139-release-tools"><label>Find an update<input id="jw139ReleaseSearch" placeholder="Search versions and changes" oninput="jw139FilterReleases(this.value)"></label></div><div id="jw139ReleaseList" class="jw139-release-list"></div>`;
 jw139FilterReleases('');
}
function jw139FilterReleases(query){
 const root=$('jw139ReleaseList');if(!root)return;
 const q=(query||'').toLowerCase().trim();
 const rows=JW139_RELEASES.filter(x=>[x.version,...x.changes].join(' ').toLowerCase().includes(q));
 root.innerHTML=rows.map((r,i)=>`<article class="jw139-release-entry"><div class="jw139-release-number"><strong>v${esc(r.version)}</strong><span>${i===0&&!q?'Latest':''}</span></div><ul>${r.changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul></article>`).join('')||'<div class="empty">No releases match your search.</div>';
}
const jw139WhatsNewRenderBase=render;
render=function(){if(page==='whatsnew'){jw138BuildNav();return jw139WhatsNew()}return jw139WhatsNewRenderBase()};



/* JWorks 14.0 — Project Workspace: additive UI, existing API and data contracts preserved. */
const JW14_PAGE_SIZE=35;
let jw14TaskPage=0,jw14ProjectPage=0,jw14TaskView='focus',jw14ProjectView='active',jw14GanttZoom='week';
function jw14Date(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s||''))return null;const d=new Date(s+'T12:00:00');return isNaN(d)?null:d}
function jw14Day(d){return Math.floor(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/86400000)}
function jw14DateLabel(s){const d=jw14Date(s);return d?d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'No due date'}
function jw14PageSlice(items,n){return items.slice(n*JW14_PAGE_SIZE,(n+1)*JW14_PAGE_SIZE)}
function jw14Pager(items,n,fn){const pages=Math.ceil(items.length/JW14_PAGE_SIZE);return pages>1?`<div class="jw14-pager"><span>${n*JW14_PAGE_SIZE+1}–${Math.min((n+1)*JW14_PAGE_SIZE,items.length)} of ${items.length}</span><button class="btn" ${n===0?'disabled':''} onclick="${fn}(${n-1})">Previous</button><button class="btn" ${n>=pages-1?'disabled':''} onclick="${fn}(${n+1})">Next</button></div>`:''}
function jw14SetTaskPage(n){jw14TaskPage=Math.max(0,n);jw14TaskResults()}
function jw14SetProjectPage(n){jw14ProjectPage=Math.max(0,n);jw14ProjectResults()}
function jw14TaskResults(){const root=$('jw14TaskResults');if(!root)return;const q=(window.taskQuery||'').trim().toLowerCase();let ts=S.tasks.filter(t=>v131TaskVisible(t)&&[t.name,t.notes,P(t.project_id)?.name].join(' ').toLowerCase().includes(q));const now=today();if(jw14TaskView==='focus')ts=ts.filter(t=>t.status!=='done'&&t.status!=='on_hold'&&(t.priority==='high'||t.due_date&&t.due_date<=now));else if(jw14TaskView==='upcoming')ts=ts.filter(t=>t.status!=='done'&&t.due_date&&t.due_date>now);else if(jw14TaskView==='open')ts=ts.filter(t=>t.status!=='done');else if(jw14TaskView==='done')ts=ts.filter(t=>t.status==='done');ts.sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999')||String(a.name).localeCompare(String(b.name)));jw14TaskPage=Math.min(jw14TaskPage,Math.max(0,Math.ceil(ts.length/JW14_PAGE_SIZE)-1));root.innerHTML=`<div class="jw14-resultbar"><strong>${ts.length} tasks</strong><span>Showing ${Math.min(JW14_PAGE_SIZE,ts.length)} per page</span></div><div class="jw14-tasklist">${jw14PageSlice(ts,jw14TaskPage).map(t=>`<div class="jw14-taskitem"><div class="jw14-taskbody"><button class="jw14-textbutton" onclick="taskDrawer('${t.id}')">${esc(t.name)}</button><div class="jw14-meta">${esc(P(t.project_id)?.name||'Personal')} · ${jw14DateLabel(t.due_date)}${t.assignee?' · '+esc(t.assignee):''}</div></div><div class="jw14-taskcontrols">${jw133Select(t.id,t.status==='in_progress'?'doing':t.status,[['todo','To Do'],['doing','Doing'],['on_hold','On Hold'],['done','Done']],'jw133TaskStatus','Task status')}${jw133Select(t.id,t.priority||'medium',[['low','Low'],['medium','Medium'],['high','High']],'jw133TaskPriority','Task priority')}</div></div>`).join('')||'<div class="jw14-empty">Nothing in this view. Try All Tasks or clear your search.</div>'}</div>${jw14Pager(ts,jw14TaskPage,'jw14SetTaskPage')}`}
function todayView(){$('main').innerHTML=title('WORKSPACE','My Work','Find what matters without scrolling through hundreds of tasks.',btn('+ Task','taskModal()','primary'))+`<div class="jw14-worktoolbar"><input aria-label="Search tasks and projects" placeholder="Search tasks or projects…" value="${esc(window.taskQuery||'')}" oninput="window.taskQuery=this.value;jw14TaskPage=0;jw14TaskResults()"><div class="jw14-viewtabs">${[['focus','Needs attention'],['upcoming','Upcoming'],['open','Open'],['all','All tasks'],['done','Completed']].map(([v,l])=>`<button class="${jw14TaskView===v?'active':''}" onclick="jw14TaskView='${v}';jw14TaskPage=0;todayView()">${l}</button>`).join('')}</div></div><div id="jw14TaskResults"></div>`;jw14TaskResults()}
function jw14ProjectResults(){const root=$('jw14ProjectResults');if(!root)return;const q=(window.projectQuery||'').trim().toLowerCase();let ps=S.projects.filter(p=>(jw14ProjectView==='all'||jw133ProjectStatus(p)===jw14ProjectView)&&[p.name,p.description,p.asset].join(' ').toLowerCase().includes(q));ps.sort((a,b)=>String(a.name).localeCompare(String(b.name)));jw14ProjectPage=Math.min(jw14ProjectPage,Math.max(0,Math.ceil(ps.length/JW14_PAGE_SIZE)-1));root.innerHTML=`<div class="jw14-resultbar"><strong>${ps.length} projects</strong><span>Open a project for its workspace</span></div><div class="jw14-projectlist">${jw14PageSlice(ps,jw14ProjectPage).map(p=>`<div class="jw14-projectitem"><button class="jw14-projecttitle" onclick="openDetail('${p.id}')"><strong>${esc(p.name)}</strong><small>${esc(p.asset||p.description||'No description')}</small></button><div class="jw14-projectprogress"><div class="jw14-progress"><span style="width:${projectStats(p.id).pct}%"></span></div><small>${projectStats(p.id).pct}% complete</small></div>${jw133Select(p.id,jw133ProjectStatus(p),[['upcoming','Upcoming'],['active','Active'],['on_hold','On Hold'],['completed','Completed']],'jw133ProjectChange','Project status')}<button class="jw133-open" onclick="openDetail('${p.id}')" aria-label="Open ${esc(p.name)}">↗</button></div>`).join('')||'<div class="jw14-empty">No projects match this view.</div>'}</div>${jw14Pager(ps,jw14ProjectPage,'jw14SetProjectPage')}`}
function projects(){$('main').innerHTML=title('PORTFOLIO','Projects','A clearer view of your project portfolio.',btn('+ New Project','projectModal()','primary'))+`<div class="jw14-worktoolbar"><input aria-label="Search projects" placeholder="Search projects…" value="${esc(window.projectQuery||'')}" oninput="window.projectQuery=this.value;jw14ProjectPage=0;jw14ProjectResults()"><div class="jw14-viewtabs">${[['active','Active'],['upcoming','Upcoming'],['on_hold','On hold'],['completed','Completed'],['all','All projects']].map(([v,l])=>`<button class="${jw14ProjectView===v?'active':''}" onclick="jw14ProjectView='${v}';jw14ProjectPage=0;projects()">${l}</button>`).join('')}</div></div><div id="jw14ProjectResults"></div>`;jw14ProjectResults()}
function fieldReportModal(){modal('Daily Field Report',`<div class="jw14-field"><div class="jw14-fieldintro"><span class="jw14-kicker">FIELD OPERATIONS / DAILY RECORD</span><h2>Document today's work</h2><p>${esc(P(projectId)?.name||'Project')} · Keep a clear record of progress, people, issues and next steps.</p></div><div class="jw14-fieldgrid"><label>Report date<input id="frdate" type="date" value="${today()}"></label><label>Contractor / crew<input id="frcontractor" placeholder="Company or contractor"></label><label>Personnel on site<input id="frpeople" placeholder="e.g. 4 technicians, 1 supervisor"></label><label>Weather / site conditions<input id="frweather" placeholder="e.g. Cloudy, 12°C"></label></div><div class="jw14-fieldsection"><h3><span>01</span> Work completed</h3><p>Activities, quantities, areas and progress achieved</p><textarea id="frwork" rows="4" placeholder="What work was completed today?"></textarea></div><div class="jw14-fieldsection"><h3><span>02</span> Issues & delays</h3><p>Deficiencies, obstacles, equipment or access issues</p><textarea id="frissues" rows="3" placeholder="Record issues or write None"></textarea></div><div class="jw14-fieldsection"><h3><span>03</span> Safety observations</h3><p>Hazards, incidents, controls and corrective actions</p><textarea id="frsafety" rows="3" placeholder="Record observations or write None"></textarea></div><div class="jw14-fieldsection"><h3><span>04</span> Next planned work</h3><p>Upcoming activities and outstanding follow-ups</p><textarea id="frnext" rows="3" placeholder="What is planned for the next shift?"></textarea></div><div class="jw14-fieldactions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveFieldReport()">Save field report</button></div></div>`);$('modal').classList.add('jw14-fieldmodal')}
const jw14CloseModalBase=closeModal;closeModal=function(){jw14CloseModalBase();$('modal')?.classList.remove('jw14-fieldmodal','jw14-ganttmodal')};
function jw14ReportHub(pid){const p=P(pid);if(!p)return;modal('Project Reports',`<div class="jw14-reporthub"><p class="muted">${esc(p.name)} · Choose how to present or preserve project information.</p><button onclick="closeModal();statusReport('${p.id}')"><strong>Status report</strong><span>Generate a standard progress summary from current project data.</span></button><button onclick="closeModal();reportBuilderV9('${p.id}')"><strong>Custom report builder</strong><span>Choose the sections and detail to include.</span></button><button onclick="closeModal();saveReportSnapshot('${p.id}')"><strong>Save snapshot</strong><span>Preserve a point-in-time record for later comparison.</span></button><button onclick="closeModal();tab='reports';render()"><strong>Report history</strong><span>Review saved reports and previous revisions.</span></button></div>`)}
function jw14GanttZoomSet(pid,v){jw14GanttZoom=v;projectGantt(pid)}
function projectGantt(pid){const p=P(pid);if(!p)return;let items=[...S.tasks.filter(t=>t.project_id===pid&&t.due_date).map(t=>({id:t.id,name:t.name,start:t.start_date||t.due_date,end:t.due_date,kind:'task',progress:Number(t.progress|| (t.status==='done'?100:0))})),...S.milestones.filter(m=>m.project_id===pid&&m.due_date).map(m=>({id:m.id,name:m.title,start:m.due_date,end:m.due_date,kind:'milestone',progress:m.done?100:0}))].filter(t=>jw14Date(t.start)&&jw14Date(t.end)).sort((a,b)=>a.start.localeCompare(b.start));const all=items.flatMap(t=>[jw14Day(jw14Date(t.start)),jw14Day(jw14Date(t.end))]);const min=all.length?Math.min(...all):jw14Day(new Date());const max=all.length?Math.max(...all):min+28;const start=min-3;const span=Math.max(14,max-start+5);const step=jw14GanttZoom==='day'?1:jw14GanttZoom==='month'?30:7;const px=jw14GanttZoom==='day'?38:jw14GanttZoom==='month'?7:15;const width=Math.max(560,span*px);let ticks='';for(let d=start;d<=start+span;d+=step){const dt=new Date(d*86400000);ticks+=`<span style="left:${(d-start)*px}px">${dt.toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span>`}const todayX=(jw14Day(new Date())-start)*px;modal('Project Schedule · '+p.name,`<div class="jw14-gantt"><div class="jw14-gantttools"><span>${items.length} scheduled items · dates from project tasks and milestones</span><div>${[['day','Day'],['week','Week'],['month','Month']].map(([v,l])=>`<button class="btn ${jw14GanttZoom===v?'primary':''}" onclick="jw14GanttZoomSet('${pid}','${v}')">${l}</button>`).join('')}</div></div><div class="jw14-ganttwrap"><div class="jw14-ganttlabels"><div class="jw14-gantthead">Task / milestone</div>${items.map(t=>`<button title="${esc(t.name)}" onclick="${t.kind==='task'?`closeModal();taskDrawer('${t.id}')`:`closeModal()`}">${esc(t.name)}<small>${jw14DateLabel(t.start)} – ${jw14DateLabel(t.end)}</small></button>`).join('')}</div><div class="jw14-ganttscroll"><div style="width:${width}px;position:relative"><div class="jw14-ganttticks">${ticks}</div>${items.map(t=>{const x=(jw14Day(jw14Date(t.start))-start)*px;const w=Math.max(8,(jw14Day(jw14Date(t.end))-jw14Day(jw14Date(t.start))+1)*px-3);return `<div class="jw14-ganttrow"><div class="jw14-ganttbar ${t.kind==='milestone'?'is-milestone':''}" style="left:${x}px;width:${w}px" title="${esc(t.name)} · ${esc(t.start)} to ${esc(t.end)}"><span style="width:${Math.max(0,Math.min(100,t.progress))}%"></span></div></div>`}).join('')}${todayX>=0&&todayX<=width?`<div class="jw14-todayline" style="left:${todayX}px"></div>`:''}</div></div></div>${items.length?'':'<div class="jw14-empty">Add start and due dates to project tasks to build the schedule.</div>'}<p class="small muted">Task bars are based on saved start/due dates. Milestones are shown as diamonds. This view does not modify dates.</p></div>`);$('modal').classList.add('jw14-ganttmodal')}
const jw14ProjectDetailBase=projectDetail;
projectDetail=function(){jw14ProjectDetailBase();const p=P(projectId);if(!p)return;const actions=document.querySelector('#main .top .actions');if(actions){const labels=['Status report','Save report snapshot','Report Builder'];for(const b of [...actions.querySelectorAll('button')])if(labels.some(l=>b.textContent.trim()===l))b.remove();const existing=[...actions.querySelectorAll('button')].find(b=>b.textContent.trim()==='Reports');if(!existing)actions.insertAdjacentHTML('beforeend',btn('Reports',`jw14ReportHub('${p.id}')`,'primary'))}const pane=$('projectPane');if(pane&&tab==='work'){const ts=S.tasks.filter(t=>t.project_id===p.id);pane.innerHTML=`<div class="jw14-resultbar"><strong>Project tasks · ${ts.length}</strong><button class="btn primary" onclick="taskModal(null,'${p.id}')">+ Task</button></div><div class="jw14-tasklist">${ts.slice(0,75).map(jw133TaskRow).join('')||'<div class="jw14-empty">No tasks yet.</div>'}</div>${ts.length>75?'<p class="small muted">Showing the first 75 tasks. Use My Work to search and filter the full task list.</p>':''}`}if(pane&&tab==='fieldreports'){pane.querySelectorAll('.phase').forEach(el=>el.classList.add('jw14-reportentry'))}}

function statusReport(pid){return generateReport(pid)}


// JWorks 14.1 — Project Command Experience
const JW141_PREF='jw141-workspace';
function jw141Read(){try{return JSON.parse(localStorage.getItem(JW141_PREF)||'{}')}catch(e){return {}}}
let jw141Prefs=Object.assign({projects:'smart',tasks:'focus',density:'balanced'},jw141Read());
function jw141Pref(k,v){jw141Prefs[k]=v;localStorage.setItem(JW141_PREF,JSON.stringify(jw141Prefs));if(k==='projects')projects();else todayView()}
function jw141Signal(p){const f=projectFacts(p.id),late=f.over.length,waiting=f.blockedN.length;let tone='good',label='On track',why='No overdue or blocked tasks';if(late){tone='risk';label='Needs attention';why=`${late} overdue task${late===1?'':'s'}`}else if(waiting){tone='warn';label='Pending dependency';why=`${waiting} task${waiting===1?'':'s'} waiting on dependencies`}else if(f.days!==null&&f.days<=14&&f.days>=0){tone='warn';label='Deadline approaching';why=`${f.days} days to target`}else if(f.days!==null&&f.days<0){tone='risk';label='Past target date';why=`${Math.abs(f.days)} days past target`}return {tone,label,why,f}}
function jw141Peek(id){const p=P(id);if(!p)return;const s=jw141Signal(p),tasks=S.tasks.filter(t=>t.project_id===id&&t.status!=='done').sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999'));modal('Project preview',`<div class="jw141-peek"><span class="jw141-kicker">PROJECT SIGNAL</span><h2>${esc(p.name)}</h2><p>${esc(p.description||p.asset||'')}</p><div class="jw141-signal ${s.tone}">${esc(s.label)} · ${esc(s.why)}</div><div class="jw141-peekstats"><div><strong>${s.f.pct}%</strong><span>Complete</span></div><div><strong>${s.f.open.length}</strong><span>Open tasks</span></div><div><strong>${s.f.over.length}</strong><span>Overdue</span></div></div><h3>Next actions</h3>${tasks.slice(0,5).map(t=>`<button class="jw141-peekrow" onclick="closeModal();taskDrawer('${t.id}')"><b>${esc(t.name)}</b><small>${esc(t.due_date||'No due date')}</small></button>`).join('')||'<p class="muted">No open tasks</p>'}<div class="jw141-actions"><button class="btn" onclick="closeModal()">Close</button><button class="btn primary" onclick="closeModal();openDetail('${p.id}')">Open project →</button></div></div>`)}
function jw141TaskWhy(t){const now=today();if(t.due_date&&t.due_date<now&&t.status!=='done')return 'Overdue since '+jw14DateLabel(t.due_date);if(t.due_date===now)return 'Due today';if(blocked(t))return 'Pending dependency';if(t.priority==='high')return 'High priority';if(t.due_date)return 'Due '+jw14DateLabel(t.due_date);return 'Open action'}
function jw141TaskRows(ts){return ts.map(t=>`<div class="jw141-workrow jw142-tone-${jw142TaskTone(t)}"><button class="jw141-taskname" onclick="taskDrawer('${t.id}')"><strong>${esc(t.name)}</strong><small>${esc(P(t.project_id)?.name||'Personal')} · ${esc(jw14DateLabel(t.due_date))}</small></button><span class="jw141-why">${esc(jw141TaskWhy(t))}</span><div class="jw141-taskactions">${jw133Select(t.id,t.status==='in_progress'?'doing':t.status,[['todo','To Do'],['doing','Doing'],['on_hold','On Hold'],['done','Done']],'jw133TaskStatus','Task status')}${jw133Select(t.id,t.priority||'medium',[['low','Low'],['medium','Medium'],['high','High']],'jw133TaskPriority','Task priority')}</div></div>`).join('')}
function jw141ProjectResults(){const root=$('jw14ProjectResults');if(!root)return;const q=(window.projectQuery||'').trim().toLowerCase();let ps=S.projects.filter(p=>(jw14ProjectView==='all'||jw133ProjectStatus(p)===jw14ProjectView)&&[p.name,p.description,p.asset].join(' ').toLowerCase().includes(q));ps.sort((a,b)=>{const x=jw141Signal(a),y=jw141Signal(b);return ({risk:0,warn:1,good:2}[x.tone]-{risk:0,warn:1,good:2}[y.tone])||a.name.localeCompare(b.name)});jw14ProjectPage=Math.min(jw14ProjectPage,Math.max(0,Math.ceil(ps.length/JW14_PAGE_SIZE)-1));root.innerHTML=`<div class="jw141-resultheading"><b>${ps.length} projects</b><span>Sorted by attention · ${jw141Prefs.projects==='smart'?'Smart portfolio':'Compact list'}</span></div><div class="jw141-projects ${jw141Prefs.projects==='smart'?'is-smart':'is-list'}">${jw14PageSlice(ps,jw14ProjectPage).map(p=>{const s=jw141Signal(p);return `<article class="jw141-project jw142-tone-${jw142ProjectTone(p)}"><div class="jw141-projectmain"><button class="jw141-projectname" onclick="jw141Peek('${p.id}')">${esc(p.name)}</button><p>${esc(p.asset||p.description||'No description')}</p>${jw141Prefs.projects==='smart'?`<span class="jw141-signal ${s.tone}">${esc(s.label)} · ${esc(s.why)}</span>`:''}</div><div class="jw141-projectright"><div class="jw141-bar"><i style="width:${s.f.pct}%"></i></div><small>${s.f.pct}% complete</small><div class="jw141-rowbuttons"><button class="btn" onclick="jw141Peek('${p.id}')">Preview</button><button class="btn primary" onclick="openDetail('${p.id}')">Open →</button></div></div></article>`}).join('')||'<div class="jw14-empty">No projects match your filters.</div>'}</div>${jw14Pager(ps,jw14ProjectPage,'jw14SetProjectPage')}`}
function projects(){$('main').innerHTML=title('PORTFOLIO','Projects','See what is moving and what needs attention.',btn('+ New Project','projectModal()','primary'))+`<div class="jw141-summary"><div><b>${S.projects.filter(p=>jw133ProjectStatus(p)==='active').length}</b><span>Active projects</span></div><div><b>${S.projects.filter(p=>jw133ProjectStatus(p)==='active'&&jw141Signal(p).tone!=='good').length}</b><span>Need attention</span></div><div><b>${S.projects.filter(p=>jw133ProjectStatus(p)==='upcoming').length}</b><span>Upcoming</span></div></div><div class="jw141-toolbar"><input aria-label="Search projects" placeholder="Search projects…" value="${esc(window.projectQuery||'')}" oninput="window.projectQuery=this.value;jw14ProjectPage=0;jw141ProjectResults()"><div class="jw141-modes"><button class="${jw141Prefs.projects==='smart'?'active':''}" onclick="jw141Pref('projects','smart')">Smart</button><button class="${jw141Prefs.projects==='list'?'active':''}" onclick="jw141Pref('projects','list')">List</button></div></div><div class="jw14-viewtabs jw141-filtertabs">${[['active','Active'],['upcoming','Upcoming'],['on_hold','On hold'],['completed','Completed'],['all','All projects']].map(([v,l])=>`<button class="${jw14ProjectView===v?'active':''}" onclick="jw14ProjectView='${v}';jw14ProjectPage=0;projects()">${l}</button>`).join('')}</div><div id="jw14ProjectResults"></div>`;jw141ProjectResults()}
function jw141TaskResults(){const root=$('jw14TaskResults');if(!root)return;const q=(window.taskQuery||'').trim().toLowerCase(),now=today();let ts=S.tasks.filter(t=>v131TaskVisible(t)&&[t.name,t.notes,P(t.project_id)?.name].join(' ').toLowerCase().includes(q));if(jw14TaskView==='focus')ts=ts.filter(t=>t.status!=='done'&&t.status!=='on_hold'&&(t.priority==='high'||t.due_date&&t.due_date<=now||blocked(t)));else if(jw14TaskView==='upcoming')ts=ts.filter(t=>t.status!=='done'&&t.due_date&&t.due_date>now);else if(jw14TaskView==='open')ts=ts.filter(t=>t.status!=='done');else if(jw14TaskView==='done')ts=ts.filter(t=>t.status==='done');ts.sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999')||a.name.localeCompare(b.name));jw14TaskPage=Math.min(jw14TaskPage,Math.max(0,Math.ceil(ts.length/JW14_PAGE_SIZE)-1));const slice=jw14PageSlice(ts,jw14TaskPage);let content='';if(jw141Prefs.tasks==='project'){const groups={};slice.forEach(t=>{const name=P(t.project_id)?.name||'Personal';(groups[name]??=[]).push(t)});content=Object.entries(groups).map(([name,rows])=>`<details class="jw141-taskgroup" open><summary>${esc(name)} <span>${rows.length} tasks</span></summary>${jw141TaskRows(rows)}</details>`).join('')}else content=jw141TaskRows(slice);root.innerHTML=`<div class="jw141-resultheading"><b>${ts.length} tasks</b><span>${jw141Prefs.tasks==='focus'?'Attention-first view':'Showing '+Math.min(JW14_PAGE_SIZE,ts.length)+' per page'}</span></div><div class="jw141-tasklist">${content||'<div class="jw14-empty">No tasks in this view.</div>'}</div>${jw14Pager(ts,jw14TaskPage,'jw14SetTaskPage')}`}
function todayView(){const open=S.tasks.filter(t=>v131TaskVisible(t)&&t.status!=='done'),now=today();$('main').innerHTML=title('WORKSPACE','My Work','Less searching. More getting things done.',btn('+ Task','taskModal()','primary'))+`<div class="jw141-summary"><div><b>${open.filter(t=>t.due_date&&t.due_date<now).length}</b><span>Overdue</span></div><div><b>${open.filter(t=>t.due_date===now).length}</b><span>Due today</span></div><div><b>${open.filter(t=>t.priority==='high').length}</b><span>High priority</span></div></div><div class="jw141-toolbar"><input aria-label="Search tasks and projects" placeholder="Search tasks or projects…" value="${esc(window.taskQuery||'')}" oninput="window.taskQuery=this.value;jw14TaskPage=0;jw141TaskResults()"><div class="jw141-modes">${[['focus','Focus'],['project','By project'],['all','All tasks']].map(([k,n])=>`<button class="${jw141Prefs.tasks===k?'active':''}" onclick="jw141Pref('tasks','${k}')">${n}</button>`).join('')}</div></div><div class="jw14-viewtabs jw141-filtertabs">${[['focus','Needs attention'],['upcoming','Upcoming'],['open','Open'],['all','All tasks'],['done','Completed']].map(([v,l])=>`<button class="${jw14TaskView===v?'active':''}" onclick="jw14TaskView='${v}';jw14TaskPage=0;todayView()">${l}</button>`).join('')}</div><div id="jw14TaskResults"></div>`;if(jw141Prefs.tasks==='all')jw14TaskView='all';else if(jw141Prefs.tasks==='focus'&&jw14TaskView==='all')jw14TaskView='focus';jw141TaskResults()}
// Rebind pager callbacks to the new result renderers.
function jw14SetTaskPage(n){jw14TaskPage=Math.max(0,n);jw141TaskResults()}
function jw14SetProjectPage(n){jw14ProjectPage=Math.max(0,n);jw141ProjectResults()}
// Field report: one scroll owner, local draft recovery, unchanged cloud save contract.
const jw141DraftKey=()=>`jw141-field-draft-${projectId}`;
const jw141FieldIds=['frdate','frcontractor','frpeople','frweather','frwork','frissues','frsafety','frnext'];
function jw141DraftSave(){const data={};jw141FieldIds.forEach(id=>data[id]=val(id));localStorage.setItem(jw141DraftKey(),JSON.stringify(data));toast('Draft saved on this device')}
function jw141DraftRestore(){try{const data=JSON.parse(localStorage.getItem(jw141DraftKey())||'null');if(data)jw141FieldIds.forEach(id=>{if($(id)&&data[id]!==undefined)$(id).value=data[id]})}catch(e){}}
function fieldReportModal(){modal('Daily Field Report',`<div class="jw141-field"><div class="jw141-fieldhero"><span class="jw141-kicker">FIELD OPERATIONS · DAILY RECORD</span><h2>Capture the day, clearly.</h2><p>${esc(P(projectId)?.name||'Project')}</p></div><div class="jw141-fieldsection"><div class="jw141-sectiontitle"><span>01</span><div><h3>Site & crew</h3><p>Who was there, and what were the conditions?</p></div></div><div class="jw141-fieldgrid"><label>Report date<input id="frdate" type="date" value="${today()}"></label><label>Contractor / crew<input id="frcontractor" placeholder="Company or contractor"></label><label>Personnel on site<input id="frpeople" placeholder="e.g. 4 technicians, 1 supervisor"></label><label>Weather / conditions<input id="frweather" placeholder="e.g. Cloudy, 12°C"></label></div></div><div class="jw141-fieldsection"><div class="jw141-sectiontitle"><span>02</span><div><h3>Work performed</h3><p>Record completed activities, quantities and locations.</p></div></div><textarea id="frwork" rows="4" placeholder="What was completed today? Include quantities and locations where relevant."></textarea></div><div class="jw141-fieldsection"><div class="jw141-sectiontitle"><span>03</span><div><h3>Issues & safety</h3><p>Document blockers and observations separately.</p></div></div><label>Issues or delays<textarea id="frissues" rows="3" placeholder="Delays, deficiencies, access constraints…"></textarea></label><label>Safety observations<textarea id="frsafety" rows="3" placeholder="Hazards, controls, incidents, or none…"></textarea></label></div><div class="jw141-fieldsection"><div class="jw141-sectiontitle"><span>04</span><div><h3>Next shift</h3><p>Leave a clear handoff for the next workday.</p></div></div><textarea id="frnext" rows="3" placeholder="Next planned work and outstanding follow-ups…"></textarea></div></div><div class="jw141-fieldsection jw142-uploadsection"><div class="jw141-sectiontitle"><span>05</span><div><h3>Photos & documents</h3><p>Attach jobsite photos, PDF reports, or supporting files (maximum 1 MB each; 5 files).</p></div></div><label class="jw142-uploadbox">＋ Add photos or files<input id="jw142-files" type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf,text/plain" onchange="jw142ChooseFiles(this.files)"></label><div id="jw142-selected" class="jw142-selected"></div></div></div><div class="jw141-fieldfooter"><span>Drafts are stored only on this device</span><div><button class="btn" onclick="jw141DraftSave()">Save draft</button><button class="btn primary" onclick="saveFieldReport()">Submit report</button></div></div>`);$('modal').classList.add('jw141-fieldmodal');const footer=$('modalBody').querySelector('.jw141-fieldfooter');if(footer)$('modal').querySelector('.dialog').appendChild(footer);jw141DraftRestore()}
const jw141SaveFieldBase=saveFieldReport;
saveFieldReport=async function(){// preserve draft if backend rejects submission
 const data={};jw141FieldIds.forEach(id=>data[id]=val(id));try{await api('field-reports','POST',{project_id:projectId,report_date:data.frdate,contractor:data.frcontractor,personnel:data.frpeople,weather:data.frweather,work_completed:data.frwork,issues:data.frissues,safety:data.frsafety,next_work:data.frnext});localStorage.removeItem(jw141DraftKey());closeModal();await refresh();toast('Field report submitted')}catch(e){toast('Could not submit report. Save a draft and retry.');console.error(e)}};
const jw141CloseModalBase=closeModal;closeModal=function(){jw141CloseModalBase();$('modal')?.classList.remove('jw141-fieldmodal');$('modal')?.querySelector('.jw141-fieldfooter')?.remove();document.body.classList.remove('jw141-modal-open')};

// v14.2: project attention and report attachments
function jw142TaskTone(t){if(t.status==='done'||t.status==='completed')return 'good';if(blocked(t)||(t.due_date&&t.due_date<today()))return 'risk';if(t.due_date){const days=Math.ceil((new Date(t.due_date+'T12:00:00')-new Date(today()+'T12:00:00'))/86400000);if(days<=7)return 'warn'}return t.status==='doing'||t.status==='in_progress'?'good':'neutral'}
function jw142ProjectTone(p){if(jw133ProjectStatus(p)==='completed')return 'good';return jw141Signal(p).tone}
let jw142Selected=[];
function jw142ChooseFiles(files){const allowed=['image/jpeg','image/png','image/webp','application/pdf','text/plain'];for(const file of Array.from(files||[])){if(!allowed.includes(file.type)||file.size>1048576){toast('Only JPG, PNG, WebP, PDF and TXT files up to 1 MB are supported');continue}if(jw142Selected.length>=5){toast('Maximum 5 files per report');break}jw142Selected.push(file)}jw142DrawFiles()}
function jw142DrawFiles(){const el=$('jw142-selected');if(el)el.innerHTML=jw142Selected.map((f,i)=>`<div class="jw142-file"><span>📎 ${esc(f.name)} · ${Math.round(f.size/1024)} KB</span><button class="btn" onclick="jw142Selected.splice(${i},1);jw142DrawFiles()">Remove</button></div>`).join('')}
const jw142OpenReport=fieldReportModal;
fieldReportModal=function(){jw142Selected=[];jw142OpenReport()};
function jw142Base64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(new Error('File read failed'));r.readAsDataURL(file)})}
// Save the report first, then attach files; failed uploads are reported and can be retried from the report.
saveFieldReport=async function(){const data={};jw141FieldIds.forEach(id=>data[id]=val(id));try{const r=await api('field-reports','POST',{project_id:projectId,report_date:data.frdate,contractor:data.frcontractor,personnel:data.frpeople,weather:data.frweather,work_completed:data.frwork,issues:data.frissues,safety:data.frsafety,next_work:data.frnext});if(!r?.id)throw new Error('No report ID returned');let errors=0;for(const file of jw142Selected){try{await api('field-report-files','POST',{report_id:r.id,name:file.name,mime:file.type,size:file.size,data:jw142Base64?await jw142Base64(file):''})}catch(e){errors++;console.error(e)}}localStorage.removeItem(jw141DraftKey());closeModal();await refresh();toast(errors?`Report saved, but ${errors} attachment(s) failed. Retry from the report.`:'Field report submitted')}catch(e){console.error(e);toast('Could not save report. Save a draft and retry.')}};
async function jw142AttachToReport(id,files){let errors=0;for(const file of Array.from(files||[])){if(file.size>1048576||!['image/jpeg','image/png','image/webp','application/pdf','text/plain'].includes(file.type)){errors++;continue}try{await api('field-report-files','POST',{report_id:id,name:file.name,mime:file.type,size:file.size,data:await jw142Base64(file)})}catch(e){errors++;console.error(e)}}await jw142LoadReportFiles();toast(errors?`${errors} file(s) could not be attached`:'Attachments saved')}
let jw142FileIndex={};
async function jw142LoadReportFiles(){try{const r=await api('field-report-files');jw142FileIndex={};for(const f of (r.files||[]))(jw142FileIndex[f.report_id]??=[]).push(f);jw142RenderFileLinks()}catch(e){console.error(e)}}
function jw142RenderFileLinks(){document.querySelectorAll('[data-jw142-report]').forEach(el=>{const id=el.dataset.jw142Report,files=jw142FileIndex[id]||[];el.innerHTML=`<div class="jw142-reportfiles">${files.map(f=>`<button class="btn" onclick="jw142Download('${f.id}')">📎 ${esc(f.name)}</button>`).join('')}<label class="jw142-addmore">＋ Attach files<input type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf,text/plain" onchange="jw142AttachToReport('${id}',this.files)"></label></div>`})}
async function jw142Download(id){try{const r=await api('field-report-files/'+id);const binary=atob(r.data);const bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes],{type:r.mime}));const a=document.createElement('a');a.href=url;a.download=r.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000)}catch(e){toast('Unable to download attachment')}}
const jw142ProjectDetailBase=projectDetail;
projectDetail=function(){jw142ProjectDetailBase();const p=P(projectId);if(!p)return;const main=$('main');main.classList.add('jw142-detail');const head=main.querySelector('.top');if(head){head.classList.add('jw142-projecthero');const actions=head.querySelector('.actions');if(actions){const buttons=[...actions.querySelectorAll('button')];const keep=['← Projects','+ Task','Reports','Ask JWorks'];const hidden=[];for(const b of buttons){const name=b.textContent.trim();if(!keep.includes(name)){hidden.push({label:name,action:b.getAttribute('onclick')});b.remove()}}const more=document.createElement('details');more.className='jw142-actionmore';more.innerHTML='<summary class="btn">More actions ▾</summary><div class="jw142-actionmenu"></div>';const box=more.querySelector('div');hidden.forEach(x=>{const b=document.createElement('button');b.textContent=x.label;b.setAttribute('onclick',x.action||'');box.appendChild(b)});actions.appendChild(more);actions.classList.add('jw142-topactions')}}const strip=main.querySelector('.v13-project-strip');if(strip)strip.classList.add('jw142-metrics');const nav=main.querySelector('.v13-project-nav');if(nav){const primary=['board','tasks','phases','milestones','files','field reports'];const buttons=[...nav.children].filter(x=>x.tagName==='BUTTON');const overflow=document.createElement('details');overflow.className='jw142-navmore';overflow.innerHTML='<summary>More ▾</summary><div class="jw142-navmenu"></div>';const menu=overflow.querySelector('div');for(const b of buttons){if(!primary.includes(b.textContent.trim().toLowerCase())){menu.appendChild(b)}}const old=nav.querySelector('details');if(old){for(const b of [...old.querySelectorAll('button')])menu.appendChild(b);old.remove()}nav.appendChild(overflow);nav.classList.add('jw142-one-line')}const pane=$('projectPane');if(pane){pane.querySelectorAll('.taskcard').forEach(el=>{const label=el.querySelector('strong')?.textContent;const task=S.tasks.find(t=>t.project_id===p.id&&t.name===label);if(task)el.classList.add('jw142-tone-'+jw142TaskTone(task))});if(tab==='fieldreports'){const entries=[...pane.querySelectorAll('.jw14-reportentry,.phase')];const reports=S.field_reports.filter(x=>x.project_id===p.id);entries.forEach((el,i)=>{if(reports[i]&&!el.querySelector('[data-jw142-report]'))el.insertAdjacentHTML('beforeend',`<div data-jw142-report="${reports[i].id}"></div>`)});jw142RenderFileLinks();jw142LoadReportFiles()}}};

// JWorks v14.3.1 corrective release: real project toolbar, unified editing, five mobile destinations.
(function(){
  // This wrapper is installed in app.js after all previous projectDetail definitions,
  // ensuring it executes on every project render rather than being overwritten by app startup.
  const previousProjectDetail=projectDetail;
  projectDetail=function(){
    previousProjectDetail();
    const project=typeof P==='function'?P(projectId):null;
    const root=document.getElementById('main');
    if(!project||!root)return;
    const hero=root.querySelector('.jw142-projecthero');
    const actions=hero?.querySelector('.jw142-topactions');
    if(!hero||!actions)return;
    root.classList.add('jw143-detail');
    const more=actions.querySelector('.jw142-actionmore');
    const all=[...actions.querySelectorAll(':scope > button'),...(more?[...more.querySelectorAll('.jw142-actionmenu button')]:[])];
    const matching=(pattern)=>all.find(b=>pattern.test(b.textContent.trim()));
    const originalBack=matching(/^←\s*projects$/i);
    const originalAdd=matching(/^\+\s*task$/i);
    const originalReports=matching(/^reports$/i);
    const originalAsk=matching(/ask jworks/i);
    if(!hero.previousElementSibling?.classList.contains('jw143-breadcrumb')){
      const back=document.createElement('button');back.type='button';back.className='jw143-breadcrumb';back.textContent='← All projects';
      back.onclick=()=>{projectId=null;render()};hero.parentNode.insertBefore(back,hero);
    }
    actions.replaceChildren();actions.classList.add('jw143-quickactions');
    const action=(label,callback,primary=false)=>{const b=document.createElement('button');b.type='button';b.className='btn'+(primary?' primary':'');b.textContent=label;b.onclick=callback;actions.appendChild(b);return b};
    if(originalAdd){originalAdd.classList.add('primary');actions.appendChild(originalAdd)}else action('+ Task',()=>taskModal(null,project.id),true);
    if(originalReports)actions.appendChild(originalReports);else action('Reports',()=>jw14ReportHub(project.id));
    action('Schedule',()=>{tab='plan';render()});
    action('Edit',()=>projectModal(project.id));
    const overflow=document.createElement('details');overflow.className='jw142-actionmore jw143-actions';
    const summary=document.createElement('summary');summary.className='btn';summary.textContent='⋯';summary.title='Additional project options';summary.setAttribute('aria-label','Additional project options');
    const menu=document.createElement('div');menu.className='jw142-actionmenu';
    overflow.append(summary,menu);
    const skip=/^(←\s*projects|\+\s*task|reports|edit project|project settings|project gantt|critical path|what-if|save report snapshot|status report|report builder)$/i;
    const seen=new Set();
    for(const b of all){const label=b.textContent.trim();if(skip.test(label)||/ask jworks/i.test(label)||seen.has(label.toLowerCase()))continue;seen.add(label.toLowerCase());b.className='';menu.appendChild(b)}
    if(originalAsk){originalAsk.className='';menu.appendChild(originalAsk)}
    if(menu.children.length)actions.appendChild(overflow);
    const nav=root.querySelector('.jw142-one-line');if(nav)nav.classList.add('jw143-project-nav');
  };
  const previousProjectModal=projectModal;
  projectModal=function(id){previousProjectModal(id);if(!id)return;
    const title=document.getElementById('modalTitle');if(title&&/project settings/i.test(title.textContent))title.textContent='Edit project';
  };
  const mobile=document.getElementById('mobileNav');
  if(mobile){
    const destinations=[['dashboard','⌂','Home'],['projects','▣','Projects'],['today','✓','My Work'],['inbox','▤','Notes'],['mobilemore','☰','More']];
    mobile.innerHTML=destinations.map(([route,icon,label])=>'<button type="button" data-mobile-page="'+route+'" aria-label="'+label+'">'+icon+'<span>'+label+'</span></button>').join('');
  }
})();
